// RMCH page bridge — GENERATED by core/bridge-bundler.mjs. Do not edit.
// Source of truth: runtime/bridge/src/parts/*.js
// Rebuild: node tools/rmch.mjs bridge-build  (the launcher also does it)
// @rmch-iife-open
//
// Bridge prelude: the injection guard and the single mutable state object every
// other part reads. Nothing here touches the game or Node — those come next
// (05-node-io) and after (10-engine), so a failure has an obvious owner.
//
// All parts are fragments of ONE function body, concatenated by
// core/bridge-bundler.mjs. This file opens it; 90-startup.js closes it. The
// bundler asserts that pairing and syntax-checks each part on its own, so an
// unbalanced brace is a build error naming the file, not a blank game window.

(function () {
  if (window.location && String(window.location.href).includes("_generated_background_page.html")) return;
  if (window.__rmchBridge) return;

  const bridge = {
    version: "0.3.1",
    startedAt: new Date().toISOString(),
    startedAtMs: Date.now(),
    processed: Object.create(null),
    originals: Object.create(null),

    // Trainer options. Persisted nowhere: the GUI is the source of truth and
    // re-sends them on connect.
    options: {
      expRate: 1,
      goldRate: 1,
      dropRate: 1,
      noSkillCost: false,
      oneHitKill: false,
      invincible: false,
      // "vitals locks" (上帝模式): HP/MP/TP held by method hooks + a guard tick.
      // Distinct from bridge.valueLocks below — see 45-vitals-locks.js.
      lockHp: false,
      lockHpMax: false,
      lockHpVal: 0,
      lockMp: false,
      lockMpVal: 0,
      lockTp: false,
      lockTpVal: 0,
      moveSpeedAdd: 0,
      gameSpeedMulti: 1,
      speedHoldCtrl: false,
      throughWalls: false,
      noEncounter: false,
      showFollowers: true,
      alwaysDash: false
    },

    // Re-entrancy counters. Each is owned by one suppression scope in
    // 20-values.js; a hook that honours a counter must say so in its own file.
    rateDepth: 0,
    suppressRates: 0,
    suppressNoCost: 0,
    suppressInvincible: 0,
    suppressLocks: 0,

    // "value locks" (数据锁定): arbitrary inventory/switch/variable/gold values
    // re-asserted every frame. The GUI owns persistence, the bridge owns the
    // live set — see 50-value-locks.js.
    valueLocks: {
      item: Object.create(null),      // id -> count
      weapon: Object.create(null),
      armor: Object.create(null),
      switch: Object.create(null),    // id -> boolean
      variable: Object.create(null),  // id -> number | string
      gold: null                      // number | null
    },
    lockStats: { applied: 0, lastAt: null, errors: 0 },

    rateStats: Object.create(null),
    battleStats: Object.create(null),
    hookTargets: [],
    hooksPatched: false,
    catalogCache: Object.create(null),
    lastError: null
  };
  window.__rmchBridge = bridge;

  // Command table. Each 6x-commands-*.js part assigns its domain onto this;
  // 69-router.js freezes it and defines execute(). Mirrors the GUI's
  // store-slice pattern (app/gui/ui/store/*.js) on purpose.
  const commandHandlers = Object.create(null);
  // ---------------------------------------------------------------------------
  // Node I/O. In a NW.js page `require` is available — but only inside the
  // game's own context. In a Tauri shell (WebView2) there is no Node at all:
  // config then comes from window.__rmchEnv and every writer below degrades
  // to a no-op, leaving the CDP outbox as the only transport (55-transport).
  // Everything below is paths + append-only writers; the JSONL files double
  // as the fallback command channel where fs exists.
  // ---------------------------------------------------------------------------

  function tryRequire(name) {
    try {
      if (typeof require === "function") return require(name);
    } catch (error) {
      bridge.lastError = String(error && error.stack || error);
    }
    return null;
  }

  const fs = tryRequire("fs");
  const path = tryRequire("path");

  // Two runtime contexts:
  //   NW.js page  — require/process exist; RMCH_* arrive via process.env.
  //   Tauri shell — no Node at all. The CDP bootstrap (core/tauri-cdp.mjs)
  //     leaves config on window.__rmchEnv and file I/O degrades to no-ops:
  //     the JSONL fallback channel, state.json and bridge.log all need fs,
  //     so under RMCH_TRANSPORT="cdp" everything moves over the CDP link.
  const envShim = window.__rmchEnv || null;
  if ((!fs || !path || typeof process === "undefined") && !envShim) {
    bridge.lastError = "Node require/process is unavailable in page context";
    return;
  }
  const fileIo = !!(fs && path);

  function envVar(name) {
    if (typeof process !== "undefined" && process.env && process.env[name]) return process.env[name];
    return (envShim && envShim[name]) || "";
  }

  // RMCH_* environment variables are set by the launcher (core/launcher.mjs).
  // State lives under <projectRoot>/runtime/bridge-state/<gameKey>/.
  const gameRoot = envVar("RMCH_GAME_ROOT") || (typeof process !== "undefined" ? process.cwd() : "");
  const projectRoot = envVar("RMCH_PROJECT_ROOT") || (fileIo ? path.join(gameRoot, "RMCH") : "");
  const gameKey = envVar("RMCH_GAME_KEY") || "unknown";
  const wsPort = Number(envVar("RMCH_WS_PORT")) || 47412;
  const wsToken = envVar("RMCH_WS_TOKEN") || "";
  const transportMode = envVar("RMCH_TRANSPORT") || "auto";
  const bridgeDir = fileIo && projectRoot ? path.join(projectRoot, "runtime", "bridge-state", gameKey) : null;
  const commandPath = bridgeDir ? path.join(bridgeDir, "commands.jsonl") : null;
  const eventPath = bridgeDir ? path.join(bridgeDir, "events.jsonl") : null;
  const statePath = bridgeDir ? path.join(bridgeDir, "state.json") : null;
  const logPath = bridgeDir ? path.join(bridgeDir, "bridge.log") : null;

  function ensureDir() {
    if (!fileIo || !bridgeDir) return;
    try {
      // existsSync first: NW.js 0.29 ships Node 9.7.1, where mkdirSync has no
      // recursive option and an existing dir throws EEXIST. The throw is
      // caught here either way — but it would pollute bridge.lastError, which
      // settleResult (55-transport.js) reports as the command's error text.
      if (!fs.existsSync(bridgeDir)) fs.mkdirSync(bridgeDir, { recursive: true });
    } catch (error) {
      bridge.lastError = String(error && error.stack || error);
    }
  }

  function append(file, value) {
    if (!fileIo || !file) return;
    ensureDir();
    fs.appendFileSync(file, JSON.stringify(value) + "\n", "utf8");
  }

  function log(message, extra) {
    if (!fileIo || !logPath) return;
    ensureDir();
    const line = `[${new Date().toISOString()}] ${message}${extra ? " " + JSON.stringify(extra) : ""}\n`;
    fs.appendFileSync(logPath, line, "utf8");
  }

  function event(command, ok, payload) {
    if (!eventPath) return;
    append(eventPath, {
      ts: Date.now(),
      commandId: command && command.__rmchQueueId || null,
      type: command && command.type,
      ok,
      payload
    });
  }

  // Every catch that wants to record a failure funnels through here, so the
  // "stack or string" dance exists once instead of in forty places.
  function noteError(error) {
    bridge.lastError = String((error && error.stack) || error);
    return bridge.lastError;
  }
  // ---------------------------------------------------------------------------
  // Engine object resolution.
  //
  // RMCH never assumes `$gameParty` is reachable by name: obfuscated/bundled
  // games (L1-L3) rename globals but keep an alias table at `TK.$`. Every
  // engine access in the bridge goes through a resolver here, so adding support
  // for another alias scheme means editing this file only.
  // ---------------------------------------------------------------------------

  function callAlias(name) {
    try {
      const tk = window.TK && window.TK.$;
      const fn = tk && tk[name];
      if (typeof fn === "function") return fn();
      return null;
    } catch (_) {
      return null;
    }
  }

  function tkValue(name) {
    try {
      const tk = window.TK && window.TK.$;
      return tk && tk[name] || null;
    } catch (_) {
      return null;
    }
  }

  // --- $game* singletons ------------------------------------------------------

  function resolveParty() { return callAlias("gameParty") || window.$gameParty || null; }
  function resolveSystem() { return callAlias("gameSystem") || window.$gameSystem || null; }
  function resolveVariables() { return callAlias("gameVariables") || window.$gameVariables || null; }
  function resolveSwitches() { return callAlias("gameSwitches") || window.$gameSwitches || null; }
  function resolveSelfSwitches() { return callAlias("gameSelfSwitches") || window.$gameSelfSwitches || null; }
  function resolveActors() { return callAlias("gameActors") || window.$gameActors || null; }
  function resolveTroop() { return callAlias("gameTroop") || window.$gameTroop || null; }
  function resolveTemp() { return callAlias("gameTemp") || window.$gameTemp || null; }
  function resolveMap() { return callAlias("gameMap") || window.$gameMap || null; }
  function resolvePlayer() { return callAlias("gamePlayer") || window.$gamePlayer || null; }
  function resolveScreen() { return callAlias("gameScreen") || window.$gameScreen || null; }

  function resolveFollowers() {
    const player = resolvePlayer();
    return player && player._followers || null;
  }

  // --- managers ---------------------------------------------------------------

  function resolveSceneManager() {
    return tkValue("SceneMrg") || tkValue("SceneManager") || window.SceneManager || null;
  }

  function resolveSceneMap() {
    return tkValue("SceneMap") || tkValue("Scene_Map") || window.Scene_Map || null;
  }

  function resolveConfigManager() {
    return tkValue("ConfigMrg") || tkValue("ConfigManager") || window.ConfigManager || null;
  }

  function resolveDataManager() {
    return tkValue("DataMrg") || window.DataManager || null;
  }

  function resolveStorageManager() {
    return tkValue("StorageMrg") || window.StorageManager || null;
  }

  function resolveImageManager() {
    return tkValue("ImageMrg") || tkValue("ImageManager") || window.ImageManager || null;
  }

  function resolveBattleManagers() {
    return uniqueTargets([
      { label: "TK.$.BattleMrg", object: tkValue("BattleMrg") },
      { label: "TK.$.BattleManager", object: tkValue("BattleManager") },
      { label: "window.BattleManager", object: window.BattleManager }
    ]);
  }

  // --- $data* tables ----------------------------------------------------------

  // kind -> [TK.$ alias getter, window global]. One table instead of the two
  // parallel maps this used to keep, which could (and did) drift apart.
  const DATA_TABLES = Object.freeze({
    item: ["dataItems", "$dataItems"],
    weapon: ["dataWeapons", "$dataWeapons"],
    armor: ["dataArmors", "$dataArmors"],
    skill: ["dataSkills", "$dataSkills"],
    state: ["dataStates", "$dataStates"],
    actor: ["dataActors", "$dataActors"],
    enemy: ["dataEnemies", "$dataEnemies"],
    troop: ["dataTroops", "$dataTroops"],
    mapInfo: ["dataMapInfos", "$dataMapInfos"],
    commonEvent: ["dataCommonEvents", "$dataCommonEvents"],
    system: ["dataSystem", "$dataSystem"]
  });

  function resolveData(kind) {
    const names = DATA_TABLES[kind];
    if (!names) return null;
    return callAlias(names[0]) || window[names[1]] || null;
  }

  function runtimeDataTable(kind) {
    const runtime = resolveData(kind);
    return Array.isArray(runtime) ? runtime : [];
  }

  // $dataSystem.switches/variables are 1-based name arrays; their length is the
  // editor-declared ceiling, which is what "id out of range" should mean.
  function systemListLimit(kind) {
    try {
      const system = resolveData("system");
      if (!system) return 0;
      if (kind === "variables") return Number(system.variables && system.variables.length || 0);
      if (kind === "switches") return Number(system.switches && system.switches.length || 0);
    } catch (_) {}
    return 0;
  }

  // --- hook targets -----------------------------------------------------------

  // Patch targets are deduplicated by identity, not by label: an alias table
  // and a window global routinely point at the same object, and patching it
  // twice would stack wrappers.
  function uniqueTargets(targets) {
    const seen = [];
    return targets.filter((target) => {
      if (!target || !target.object || seen.includes(target.object)) return false;
      seen.push(target.object);
      return true;
    });
  }

  function resolvePrototypeTargets(globalName, aliases) {
    const candidates = [{ label: `window.${globalName}`, object: window[globalName] }];
    (aliases || []).forEach((name) => candidates.push({ label: `TK.$.${name}`, object: tkValue(name) }));
    return uniqueTargets(candidates
      .map((candidate) => {
        const ctor = candidate.object;
        return ctor && ctor.prototype ? { label: `${candidate.label}.prototype`, object: ctor.prototype } : null;
      }));
  }

  // Bundled games sometimes expose no constructor at all — the only handle on
  // the class is a live instance, so walk its prototype chain instead.
  function runtimePrototypeChainTargets(label, object, maxDepth) {
    const targets = [];
    try {
      let prototype = object && Object.getPrototypeOf(object);
      let depth = 1;
      while (prototype && prototype !== Object.prototype && depth <= maxDepth) {
        targets.push({ label: `${label}.prototype${depth}`, object: prototype });
        prototype = Object.getPrototypeOf(prototype);
        depth += 1;
      }
    } catch (_) {}
    return targets;
  }

  // flatMap one level without Array.prototype.flatMap: MV games on NW.js 0.29
  // (Chromium 65) do not have it, and this runs on the hook hot path for every
  // engine generation.
  function flatMapOne(list, fn) {
    const out = [];
    list.forEach((item, index) => {
      const mapped = fn(item, index);
      for (let i = 0; i < mapped.length; i += 1) out.push(mapped[i]);
    });
    return out;
  }

  function partyMemberPrototypeTargets(label) {
    return flatMapOne(getPartyMembers(resolveParty()), (actor, index) => {
      const actorId = actorIdOf(actor) || index + 1;
      return runtimePrototypeChainTargets(`${label}.actor${actorId}`, actor, 5);
    });
  }

  function troopEnemyPrototypeTargets(label) {
    return flatMapOne(troopEnemies(false), (enemy, index) => {
      let enemyId = index + 1;
      try {
        enemyId = typeof enemy.enemyId === "function" ? enemy.enemyId() : enemy._enemyId || enemyId;
      } catch (_) {}
      return runtimePrototypeChainTargets(`${label}.enemy${enemyId}`, enemy, 5);
    });
  }

  // The player is patched from two angles for the same reason as above.
  // patchMoveSpeed and patchEncounter both want this list.
  function playerPrototypeTargets() {
    const player = resolvePlayer();
    return uniqueTargets([
      { label: "window.Game_Player.prototype", object: window.Game_Player && window.Game_Player.prototype },
      { label: "runtime player chain", object: player && Object.getPrototypeOf(player) }
    ]);
  }

  // --- save directory ---------------------------------------------------------

  function saveDirPath() {
    // Prefer the game's own StorageManager directory; fall back to scanning
    // the common layouts (www/save, save).
    try {
      const storage = resolveStorageManager();
      if (storage && typeof storage.localFileDirectoryPath === "function") {
        const dir = storage.localFileDirectoryPath();
        if (dir) return String(dir);
      }
    } catch (_) {}
    // The launcher can pin it explicitly — Tauri shells have no fs to scan
    // with, and their save dir convention is <gameRoot>/save.
    const pinned = envVar("RMCH_SAVE_DIR");
    if (pinned) return pinned;
    if (fs && path) {
      for (const candidate of [path.join(gameRoot, "www", "save"), path.join(gameRoot, "save")]) {
        if (fs.existsSync(candidate)) return candidate;
      }
      return path.join(gameRoot, "www", "save");
    }
    return gameRoot ? gameRoot + "\\save" : "save";
  }
  // ---------------------------------------------------------------------------
  // Value coercion, argument guards, re-entrancy scopes, hook counters.
  //
  // Command args arrive as JSON from the GUI, so every number is "maybe a
  // string, maybe empty, maybe absent". loose* tolerates, require* throws with a
  // message the GUI shows verbatim.
  // ---------------------------------------------------------------------------

  function toBool(value) {
    return value === true || value === "true" || value === 1 || value === "1";
  }

  function clampNumber(value, min, max, fallback) {
    const number = Number(value);
    if (!Number.isFinite(number)) return fallback;
    return Math.min(max, Math.max(min, number));
  }

  function looseNumber(value, fallback) {
    const number = Number(value);
    return Number.isFinite(number) ? number : (fallback || 0);
  }

  function requireNumber(value, label) {
    const number = Number(value);
    if (!Number.isFinite(number)) throw new Error(`${label || "value"} must be a number`);
    return number;
  }

  function requireId(value, label) {
    const id = Math.floor(requireNumber(value, label));
    if (id <= 0) throw new Error(`${label || "id"} must be positive`);
    return id;
  }

  // "Was this arg supplied at all?" — the GUI sends "" for a cleared field.
  function hasValue(value) {
    return value !== undefined && value !== null && value !== "";
  }

  function clampCurrentValue(value, maxValue, fallbackMax) {
    const raw = Math.floor(requireNumber(value, "value"));
    const max = Number.isFinite(Number(maxValue)) && Number(maxValue) > 0
      ? Number(maxValue)
      : fallbackMax;
    return Math.min(max, Math.max(0, raw));
  }

  // --- engine-object guards ---------------------------------------------------
  //
  // Commands used to repeat `const p = resolveParty(); if (!p) throw ...` a
  // couple of dozen times, with the message drifting between copies.

  function requireEngineObject(object, label, method) {
    if (!object) throw new Error(`${label} is unavailable`);
    if (method && typeof object[method] !== "function") {
      throw new Error(`${label}.${method} is unavailable`);
    }
    return object;
  }

  function requireParty(method) { return requireEngineObject(resolveParty(), "game party", method); }
  function requirePlayer(method) { return requireEngineObject(resolvePlayer(), "game player", method); }
  function requireMap(method) { return requireEngineObject(resolveMap(), "game map", method); }
  function requireSwitches() { return requireEngineObject(resolveSwitches(), "game switches", "setValue"); }
  function requireVariables() { return requireEngineObject(resolveVariables(), "game variables", "setValue"); }
  function requireSelfSwitches() { return requireEngineObject(resolveSelfSwitches(), "game self switches", "setValue"); }
  function requireSceneManager(method) { return requireEngineObject(resolveSceneManager(), "SceneManager", method); }
  function requireDataManager(method) { return requireEngineObject(resolveDataManager(), "DataManager", method); }

  function requireJsonEx(method) {
    return requireEngineObject(window.JsonEx, "JsonEx", method);
  }

  // --- re-entrancy scopes -----------------------------------------------------
  //
  // A trainer write must not be amplified by the trainer's own hooks: setting
  // gold to 10000 should not run through the goldRate multiplier. Each scope
  // bumps a counter that the matching hook checks. The counter it bumps and the
  // hook that reads it are named the same on purpose — if you add a scope here,
  // grep for its counter and make sure something honours it.

  function suppressionScope(counter) {
    return function (fn) {
      bridge[counter] += 1;
      try {
        return fn();
      } finally {
        bridge[counter] = Math.max(0, bridge[counter] - 1);
      }
    };
  }

  const withRatesSuppressed = suppressionScope("suppressRates");       // 40-hooks: rate multipliers
  const withLocksSuppressed = suppressionScope("suppressLocks");       // 45-vitals + 50-value-locks
  const withNoCostSuppressed = suppressionScope("suppressNoCost");     // 40-hooks: skill cost waiver
  const withInvincibleSuppressed = suppressionScope("suppressInvincible"); // 45-vitals: damage block

  // --- hook counters ----------------------------------------------------------
  //
  // Diagnostics only: "did the exp multiplier actually fire?" is otherwise
  // unanswerable from outside the game process.

  function bumpStat(table, name, payload) {
    table[name] = Number(table[name] || 0) + 1;
    if (payload) table.last = { name, ts: Date.now(), ...payload };
  }

  function bumpRateStat(name, payload) { bumpStat(bridge.rateStats, name, payload); }
  function bumpBattleStat(name, payload) { bumpStat(bridge.battleStats, name, payload); }

  function scaledPositiveAmount(amount, rate) {
    const number = Number(amount);
    if (!Number.isFinite(number) || number <= 0) return amount;
    return Math.max(0, Math.floor(number * rate));
  }

  // --- value shaping for the wire ---------------------------------------------

  // Calls a getter that may not exist / may throw / may return a live engine
  // object. Objects collapse to null because these feed JSON state snapshots,
  // where a Game_Actor reference would either explode or leak the whole graph.
  function safeCall(fn) {
    try {
      const value = fn();
      return typeof value === "object" && value !== null ? null : value;
    } catch (_) {
      return null;
    }
  }

  // console.eval results: depth- and width-limited so a stray `$gameMap` can't
  // serialise a megabyte of tilemap into the response.
  function compactRuntimeValue(value, depth) {
    if (value === null || value === undefined) return value;
    if (typeof value === "number" || typeof value === "boolean") return value;
    if (typeof value === "string") return value.length > 200 ? value.slice(0, 200) + "..." : value;
    if (typeof value === "function") return `[fn ${value.name || "anonymous"}]`;
    if (depth <= 0) return "[object]";
    if (Array.isArray(value)) {
      return {
        type: "array",
        length: value.length,
        items: value.slice(0, 20).map((item) => compactRuntimeValue(item, depth - 1))
      };
    }
    if (typeof value === "object") {
      const output = {};
      Object.keys(value).slice(0, 24).forEach((key) => {
        try {
          output[key] = compactRuntimeValue(value[key], depth - 1);
        } catch (error) {
          output[key] = { error: String(error && error.message || error) };
        }
      });
      return output;
    }
    return String(value);
  }
  // ---------------------------------------------------------------------------
  // Battlers, party, troop.
  //
  // The recurring hazard: MV exposes hp/level/name as prototype METHODS, MZ as
  // GETTERS, and plugin-heavy games override either. readStat() accepts all
  // three shapes and every accessor here is built on it, so nothing in the
  // bridge should ever read `actor.hp` directly.
  // ---------------------------------------------------------------------------

  function readStat(object, name, fallbackField) {
    try {
      const value = object[name];
      if (typeof value === "function") return value.call(object);
      if (value !== undefined && value !== null) return value;
      return fallbackField ? object[fallbackField] : null;
    } catch (_) {
      return fallbackField ? object[fallbackField] : null;
    }
  }

  function safeGold(party) {
    if (!party) return null;
    try {
      if (typeof party.gold === "function") return party.gold();
      if (typeof party._gold === "number") return party._gold;
    } catch (_) {}
    return null;
  }

  // --- battler identity -------------------------------------------------------

  function isActorBattler(battler) {
    try {
      if (!battler) return false;
      if (typeof battler.isActor === "function") return !!battler.isActor();
      return actorIdOf(battler) != null;
    } catch (_) {
      return false;
    }
  }

  function isEnemyBattler(battler) {
    try {
      return !!(battler && typeof battler.isEnemy === "function" && battler.isEnemy());
    } catch (_) {
      return false;
    }
  }

  function battlerHp(battler) {
    if (!battler) return 0;
    return Math.max(0, Number(readStat(battler, "hp", "_hp")) || 0);
  }

  function setBattlerHp(battler, value) {
    if (!battler) return;
    withLocksSuppressed(() => {
      if (typeof battler.setHp === "function") battler.setHp(value);
      else battler._hp = value;
    });
  }

  // --- battle state -----------------------------------------------------------

  function isInBattle() {
    try {
      const managers = resolveBattleManagers();
      const battle = managers[0] && managers[0].object;
      if (battle && battle._phase && battle._phase !== "init") return true;
    } catch (_) {}
    return false;
  }

  // Rate multipliers apply to battle rewards only — scaling a quest reward or a
  // shop refund by expRate would be indistinguishable from a bug.
  function isInBattleRewardContext() {
    if (bridge.rateDepth > 0) return true;
    try {
      const party = resolveParty();
      if (party && typeof party.inBattle === "function" && party.inBattle()) return true;
    } catch (_) {}
    return isInBattle();
  }

  // --- party ------------------------------------------------------------------

  function getPartyMembers(party) {
    if (!party) return [];
    try {
      if (typeof party.allMembers === "function") return party.allMembers().filter(Boolean);
      if (typeof party.members === "function") return party.members().filter(Boolean);
    } catch (_) {}
    return [];
  }

  function partyBattleMembers() {
    const party = resolveParty();
    if (!party) return [];
    try {
      if (typeof party.battleMembers === "function") return party.battleMembers().filter(Boolean);
    } catch (_) {}
    return getPartyMembers(party).slice(0, 4);
  }

  function requireActor(actorId) {
    const actors = resolveActors();
    let actor = null;
    try {
      if (actors && typeof actors.actor === "function") actor = actors.actor(actorId);
    } catch (_) {}
    // Game_Actors._data is an array in stock RPG Maker but a sparse object in
    // some bundled games.
    if (!actor && actors) {
      const data = actors._data;
      if (Array.isArray(data)) actor = data[actorId];
      else if (data && typeof data === "object") actor = data[actorId];
    }
    if (!actor) throw new Error(`actor ${actorId} is unavailable`);
    return actor;
  }

  function actorIdOf(actor) {
    if (!actor) return null;
    try {
      if (typeof actor.actorId === "function") return actor.actorId();
      return actor._actorId || null;
    } catch (_) {
      return null;
    }
  }

  function actorNameOf(actor) {
    if (!actor) return "";
    try {
      if (typeof actor.name === "function") return actor.name();
      const data = typeof actor.actor === "function" ? actor.actor() : null;
      return data && data.name || actor._name || "";
    } catch (_) {
      return "";
    }
  }

  // --- troop ------------------------------------------------------------------

  function troopEnemies(aliveOnly) {
    const troop = resolveTroop();
    if (!troop) return [];
    let members = [];
    try {
      if (typeof troop.members === "function") members = troop.members().filter(Boolean);
    } catch (_) {}
    if (aliveOnly) {
      members = members.filter((enemy) => {
        try {
          return typeof enemy.isAlive === "function" ? enemy.isAlive() : battlerHp(enemy) > 0;
        } catch (_) {
          return true;
        }
      });
    }
    return members;
  }

  function enemyNameOf(enemy) {
    if (!enemy) return "";
    try {
      if (typeof enemy.name === "function") return String(enemy.name() || "");
      const data = typeof enemy.enemy === "function" ? enemy.enemy() : null;
      if (data && data.name) return String(data.name);
      const id = typeof enemy.enemyId === "function" ? enemy.enemyId() : enemy._enemyId;
      const entry = id ? runtimeDataTable("enemy")[id] : null;
      return entry && entry.name ? String(entry.name) : "";
    } catch (_) {
      return "";
    }
  }

  // --- refresh ----------------------------------------------------------------

  function refreshActor(actor) {
    try {
      if (actor && typeof actor.refresh === "function") actor.refresh();
    } catch (_) {}
  }

  // After a trainer write the on-screen windows still show the old numbers.
  // Refreshing every window the scene owns is blunt but engine-agnostic.
  function refreshMapAndWindows() {
    try {
      const map = resolveMap();
      if (map && typeof map.requestRefresh === "function") map.requestRefresh();
    } catch (_) {}
    try {
      const scene = resolveSceneManager() && resolveSceneManager()._scene;
      if (scene) {
        for (const key of Object.keys(scene)) {
          const child = scene[key];
          if (child && typeof child.refresh === "function") {
            try { child.refresh(); } catch (_) {}
          }
        }
      }
    } catch (_) {}
  }

  // --- actor snapshot ---------------------------------------------------------

  // One actor as plain JSON, for the state snapshot and the 数据 tab's detail
  // editor. Every field is guarded independently: a game that breaks `states()`
  // should still report level and HP, not collapse the whole record to null.
  function actorInfo(actor) {
    if (!actor) return null;

    // arrayField is the id-only fallback (`_skills`, `_states`); omit it where
    // there is no meaningful one (equips are objects, not ids).
    const entryList = (methodName, arrayField) => {
      try {
        if (typeof actor[methodName] === "function") {
          return actor[methodName]().filter(Boolean).map((entry) => ({ id: entry.id, name: entry.name }));
        }
        if (arrayField && Array.isArray(actor[arrayField])) {
          return actor[arrayField].map((id) => ({ id, name: "" }));
        }
      } catch (_) {}
      return [];
    };

    let params = null;
    try {
      if (typeof actor.param === "function") {
        params = [];
        for (let index = 0; index < 8; index += 1) params.push(Number(actor.param(index)) || 0);
      }
    } catch (_) { params = null; }

    let className = null;
    try {
      const klass = typeof actor.currentClass === "function" ? actor.currentClass() : null;
      className = klass && klass.name || null;
    } catch (_) { className = null; }

    return {
      id: actorIdOf(actor),
      name: actorNameOf(actor),
      nickname: typeof actor.nickname === "function" ? safeCall(() => actor.nickname()) : null,
      classId: Number(actor._classId) || null,
      className,
      level: readStat(actor, "level", "_level"),
      maxLevel: typeof actor.maxLevel === "function" ? safeCall(() => actor.maxLevel()) : null,
      exp: typeof actor.currentExp === "function" ? safeCall(() => actor.currentExp()) : null,
      nextLevelExp: typeof actor.nextLevelExp === "function" ? safeCall(() => actor.nextLevelExp()) : null,
      hp: readStat(actor, "hp", "_hp"),
      mhp: readStat(actor, "mhp", "_mhp"),
      mp: readStat(actor, "mp", "_mp"),
      mmp: readStat(actor, "mmp", "_mmp"),
      tp: readStat(actor, "tp", "_tp"),
      maxTp: typeof actor.maxTp === "function" ? safeCall(() => actor.maxTp()) : null,
      params,
      paramPlus: Array.isArray(actor._paramPlus) ? actor._paramPlus.slice() : null,
      skills: entryList("skills", "_skills"),
      states: entryList("states", "_states"),
      equips: entryList("equips")
    };
  }
  // ---------------------------------------------------------------------------
  // Catalogs and map data.
  //
  // Item/skill/map lists are read from the game's LIVE data tables, never by
  // decrypting data files: an L1/L2 game decrypts its own JSON at boot, and by
  // the time the bridge is asked for a catalog the plaintext is sitting in
  // memory. Cost: queries before the game finishes loading see a short table,
  // which is what the cache-invalidation rule below exists to survive.
  // ---------------------------------------------------------------------------

  const CATALOG_KINDS = Object.freeze([
    "item", "weapon", "armor", "skill", "state",
    "actor", "enemy", "troop", "mapInfo", "commonEvent"
  ]);

  // Party inventory kind -> Game_Party storage field. Three call sites needed
  // this mapping (item.list, item.set, value-lock writeback) and each used to
  // spell it out inline.
  const INVENTORY_SLOTS = Object.freeze([
    ["item", "_items"],
    ["weapon", "_weapons"],
    ["armor", "_armors"]
  ]);

  function inventorySlot(kind) {
    const found = INVENTORY_SLOTS.find((pair) => pair[0] === kind);
    return found ? found[1] : null;
  }

  function normalizeDropKind(kind) {
    const value = String(kind || "item").toLowerCase();
    return inventorySlot(value) ? value : null;
  }

  function catalogEntries(kind, { query = "", limit = 500 } = {}) {
    const table = runtimeDataTable(kind);
    let cached = bridge.catalogCache[kind];
    // The cache is only valid while the backing table keeps its shape: a
    // catalog queried mid-boot (or before an L1/L2 game decrypts its data)
    // would otherwise freeze the empty list in place for the whole session.
    if (!cached || cached.tableLength !== table.length || !cached.entries.length) {
      const entries = [];
      for (let id = 1; id < table.length; id += 1) {
        const entry = table[id];
        if (!entry) continue;
        entries.push({
          id,
          name: entry.name || "",
          iconIndex: entry.iconIndex != null ? entry.iconIndex : null,
          note: entry.note != null ? String(entry.note).slice(0, 300) : ""
        });
      }
      cached = { tableLength: table.length, entries };
      if (entries.length) bridge.catalogCache[kind] = cached;
    }
    let entries = cached.entries;
    if (query) {
      const lower = String(query).toLowerCase();
      entries = entries.filter((entry) => entry.name.toLowerCase().includes(lower) || String(entry.id) === lower);
    }
    return {
      total: entries.length,
      entries: entries.slice(0, limit).map((entry) => ({ ...entry }))
    };
  }

  function requireDataEntry(kind, id, label) {
    const number = requireId(id, label || `${kind} id`);
    const table = runtimeDataTable(kind);
    const entry = table && table[number];
    if (!entry) throw new Error(`${kind} ${number} not found`);
    return { id: number, entry };
  }

  // --- switches / variables listing -------------------------------------------

  // $dataSystem holds the names, $gameSwitches/$gameVariables hold the values;
  // the GUI wants them zipped, paged.
  function listSystemEntries(kind, args) {
    const system = resolveData("system");
    if (!system) throw new Error("$dataSystem is unavailable");
    const names = kind === "switches" ? system.switches : system.variables;
    if (!Array.isArray(names)) throw new Error(`system ${kind} list is unavailable`);
    const store = kind === "switches" ? resolveSwitches() : resolveVariables();
    const offset = Math.max(0, Math.floor(looseNumber(args.offset, 0)));
    const limit = Math.max(1, Math.min(2000, Math.floor(looseNumber(args.limit, 200))));
    const entries = [];
    const end = Math.min(names.length, offset + limit);
    for (let id = Math.max(1, offset); id < end; id += 1) {
      let value = null;
      try {
        value = store && typeof store.value === "function" ? store.value(id) : null;
      } catch (_) {}
      entries.push({ id, name: names[id] || "", value });
    }
    return { total: Math.max(0, names.length - 1), offset, limit, entries };
  }

  // --- maps -------------------------------------------------------------------

  function currentMapInfo() {
    const map = resolveMap();
    const player = resolvePlayer();
    const mapInfoTable = runtimeDataTable("mapInfo");
    let name = "";
    try {
      const mapId = map && map._mapId;
      const info = mapId != null && mapInfoTable[mapId];
      name = info && info.name || "";
    } catch (_) {}
    return {
      mapId: map ? map._mapId : null,
      mapName: name,
      displayName: map && map._displayName || "",
      x: player ? player._x : null,
      y: player ? player._y : null,
      direction: player ? player._direction : null,
      width: map ? safeCall(() => map.width()) : null,
      height: map ? safeCall(() => map.height()) : null
    };
  }

  function mapList() {
    const table = runtimeDataTable("mapInfo");
    const entries = [];
    for (let id = 1; id < table.length; id += 1) {
      const info = table[id];
      if (!info) continue;
      entries.push({
        id,
        name: info.name || "",
        parentId: info.parentId != null ? info.parentId : null,
        order: info.order != null ? info.order : null
      });
    }
    return { total: entries.length, entries };
  }
  // ---------------------------------------------------------------------------
  // Trainer hooks.
  //
  // patchMethod stashes every original in bridge.originals, so the whole
  // installation is reversible and a double-patch is impossible. Installers are
  // idempotent by design: patchTrainerHooks() is re-run on a timer while the
  // engine is still defining classes, and again on window load.
  //
  // Vitals (HP/MP/TP) locking lives in 45-vitals-locks.js and per-frame value
  // locking in 50-value-locks.js; this file owns rates, encounters, movement,
  // skill cost and the scene-update wrapper they share.
  // ---------------------------------------------------------------------------

  function patchMethod(owner, name, key, wrapper) {
    if (!owner || typeof owner[name] !== "function") return false;
    if (owner[name].__rmchPatched) return true;
    if (!bridge.originals[key]) bridge.originals[key] = owner[name];
    const original = bridge.originals[key];
    const patched = function () {
      return wrapper.call(this, original, arguments);
    };
    Object.defineProperty(patched, "__rmchPatched", { value: true, configurable: true });
    owner[name] = patched;
    return true;
  }

  // --- options ----------------------------------------------------------------

  const RATE_OPTIONS = Object.freeze(["expRate", "goldRate", "dropRate"]);
  const NUMBER_OPTIONS = Object.freeze(["lockHpVal", "lockMpVal", "lockTpVal", "moveSpeedAdd", "gameSpeedMulti"]);
  const BOOL_OPTIONS = Object.freeze([
    "noSkillCost", "oneHitKill", "invincible",
    "lockHp", "lockHpMax", "lockMp", "lockTp",
    "speedHoldCtrl", "throughWalls", "noEncounter", "alwaysDash", "showFollowers"
  ]);

  function setTrainerOptions(options) {
    if (!options || typeof options !== "object") return { ...bridge.options };
    const given = (key) => Object.prototype.hasOwnProperty.call(options, key);

    RATE_OPTIONS.forEach((key) => {
      if (given(key)) bridge.options[key] = clampNumber(options[key], 0, 999, bridge.options[key]);
    });
    NUMBER_OPTIONS.forEach((key) => {
      if (!given(key)) return;
      // gameSpeedMulti multiplies frame time, so below 1 would run the game
      // backwards-ish; the rest may legitimately be negative (moveSpeedAdd).
      const min = key === "gameSpeedMulti" ? 1 : -9999;
      bridge.options[key] = clampNumber(options[key], min, 9999, bridge.options[key]);
    });
    BOOL_OPTIONS.forEach((key) => {
      if (given(key)) bridge.options[key] = toBool(options[key]);
    });

    patchTrainerHooks();
    applyWorldOptions();
    return { ...bridge.options };
  }

  // Options that map to plain game fields rather than method hooks. The game
  // writes these too, so 90-startup re-applies them on a timer.
  function applyWorldOptions() {
    try {
      const player = resolvePlayer();
      if (player && Object.prototype.hasOwnProperty.call(player, "_through")) {
        player._through = !!bridge.options.throughWalls;
      }
      const followers = resolveFollowers();
      if (followers && "_visible" in followers) {
        followers._visible = !!bridge.options.showFollowers;
      }
      const config = resolveConfigManager();
      if (config && "alwaysDash" in config) {
        config.alwaysDash = !!bridge.options.alwaysDash;
      }
    } catch (error) {
      noteError(error);
    }
  }

  // --- movement / encounters --------------------------------------------------

  function patchMoveSpeed() {
    let patched = false;
    playerPrototypeTargets().forEach((target) => {
      if (patchMethod(target.object, "realMoveSpeed", `${target.label}.realMoveSpeed`, function (original, args) {
        const base = Number(original.apply(this, args)) || 0;
        if (!bridge.options.moveSpeedAdd) return base;
        // RPG Maker treats speed as 1..6; outside that range animation breaks.
        return Math.max(1, Math.min(6, base + bridge.options.moveSpeedAdd));
      })) patched = true;
    });
    return patched;
  }

  function patchEncounter() {
    let patched = false;
    playerPrototypeTargets().forEach((target) => {
      if (patchMethod(target.object, "meetsEncounterConditions", `${target.label}.meetsEncounterConditions`, function (original, args) {
        if (bridge.options.noEncounter) return false;
        return original.apply(this, args);
      })) patched = true;
      if (patchMethod(target.object, "encounterProgressValue", `${target.label}.encounterProgressValue`, function (original, args) {
        if (bridge.options.noEncounter) return 0;
        return original.apply(this, args);
      })) patched = true;
    });
    return patched;
  }

  // --- scene update: game speed + value locks ---------------------------------

  // Both concerns share SceneManager.updateMain because patchMethod refuses to
  // wrap the same method twice. Keep them in this order: locks must be
  // re-asserted after the game's own frame has run, not before.
  function patchSceneUpdate() {
    const sceneManager = resolveSceneManager();
    if (!sceneManager) return false;
    return patchMethod(sceneManager, "updateMain", "SceneManager.updateMain", function (original, args) {
      const result = original.apply(this, args);
      if (bridge.options.speedHoldCtrl && bridge.keysHeld && (bridge.keysHeld.control || bridge.keysHeld[17])) {
        const delta = args && args[0];
        if (Number.isFinite(delta)) {
          const extra = delta * (clampNumber(bridge.options.gameSpeedMulti, 1, 20, 1) - 1);
          try { original.call(this, extra); } catch (_) {}
        }
      }
      applyValueLocks();
      return result;
    });
  }

  function hookKeyboard() {
    try {
      if (bridge.keysHooked) return true;
      const setControl = (held) => (domEvent) => {
        if (!bridge.keysHeld) bridge.keysHeld = Object.create(null);
        if (domEvent.key === "Control" || domEvent.keyCode === 17) bridge.keysHeld.control = held;
      };
      // Capture phase: the game installs its own keydown handler and may stop
      // propagation.
      window.addEventListener("keydown", setControl(true), true);
      window.addEventListener("keyup", setControl(false), true);
      bridge.keysHooked = true;
      return true;
    } catch (_) {
      return false;
    }
  }

  // --- battle rewards (exp / gold / drop rates) -------------------------------

  // Rewards are recomputed from a cached base, not multiplied in place: this
  // runs on both makeRewards and gainRewards, and multiplying twice would
  // compound the rate (the bug the zs2 modkit hit first).
  function applyRewards(manager) {
    const rewards = manager && manager._rewards;
    if (!rewards) return false;
    if (!rewards.__rmchBaseRewards) {
      const baseRewards = { exp: Number(rewards.exp || 0), gold: Number(rewards.gold || 0) };
      try {
        Object.defineProperty(rewards, "__rmchBaseRewards", { value: baseRewards, configurable: true });
      } catch (_) {
        rewards.__rmchBaseRewards = baseRewards;
      }
    }
    rewards.exp = Math.max(0, Math.floor(rewards.__rmchBaseRewards.exp * bridge.options.expRate));
    rewards.gold = Math.max(0, Math.floor(rewards.__rmchBaseRewards.gold * bridge.options.goldRate));
    bumpRateStat("battleRewards", {
      exp: rewards.exp,
      gold: rewards.gold,
      expRate: bridge.options.expRate,
      goldRate: bridge.options.goldRate
    });
    return true;
  }

  function patchBattleRewards(track) {
    resolveBattleManagers().forEach((target) => {
      track(patchMethod(target.object, "makeRewards", `${target.label}.makeRewards`, function (original, args) {
        const result = original.apply(this, args);
        applyRewards(this);
        return result;
      }), `${target.label}.makeRewards`);
      track(patchMethod(target.object, "gainRewards", `${target.label}.gainRewards`, function (original, args) {
        const scaled = applyRewards(this);
        // The rewards object is already scaled, so the per-actor gainExp /
        // party gainGold hooks below must not scale it a second time.
        return scaled
          ? withRatesSuppressed(() => original.apply(this, args))
          : original.apply(this, args);
      }), `${target.label}.gainRewards`);
    });
  }

  // gainExp / gainGold are also called outside battle (quest rewards, events),
  // where a trainer multiplier would look like corruption. Hence the
  // isInBattleRewardContext guard.
  function patchScaledGain(track, targets, methodName, rateKey, statName) {
    targets.forEach((target) => {
      track(patchMethod(target.object, methodName, `${target.label}.${methodName}`, function (original, args) {
        if (bridge.suppressRates > 0 || bridge.options[rateKey] === 1 || !isInBattleRewardContext()) {
          return original.apply(this, args);
        }
        const next = Array.prototype.slice.call(args);
        const base = Number(next[0] || 0);
        next[0] = scaledPositiveAmount(next[0], bridge.options[rateKey]);
        bumpRateStat(statName, { base, value: next[0], rate: bridge.options[rateKey] });
        return original.apply(this, next);
      }), `${target.label}.${methodName}`);
    });
  }

  function patchDropRate(track) {
    const targets = resolvePrototypeTargets("Game_Enemy", ["GameEnemy"])
      .concat(troopEnemyPrototypeTargets("runtime.troop"));
    targets.forEach((target) => {
      track(patchMethod(target.object, "dropItemRate", `${target.label}.dropItemRate`, function (original, args) {
        const base = Number(original.apply(this, args) || 0);
        const value = Math.max(0, base * bridge.options.dropRate);
        bumpRateStat("dropItemRate", { base, value, rate: bridge.options.dropRate });
        return value;
      }), `${target.label}.dropItemRate`);
    });
  }

  // --- skill cost -------------------------------------------------------------

  function patchSkillCost(track) {
    const targets = resolvePrototypeTargets("Game_BattlerBase", ["GameBattlerBase"])
      .concat(partyMemberPrototypeTargets("runtime.party"));
    // suppressNoCost lets a profile deliberately charge a cost while the option
    // is on (api.helpers.withNoCostSuppressed).
    const waived = (battler) => bridge.suppressNoCost <= 0
      && bridge.options.noSkillCost
      && isActorBattler(battler);

    targets.forEach((target) => {
      track(patchMethod(target.object, "canPaySkillCost", `${target.label}.canPaySkillCost`, function (original, args) {
        if (waived(this)) return true;
        return original.apply(this, args);
      }), `${target.label}.canPaySkillCost`);
      track(patchMethod(target.object, "paySkillCost", `${target.label}.paySkillCost`, function (original, args) {
        if (waived(this)) return;
        return original.apply(this, args);
      }), `${target.label}.paySkillCost`);
      track(patchMethod(target.object, "skillMpCost", `${target.label}.skillMpCost`, function (original, args) {
        if (waived(this)) return 0;
        return original.apply(this, args);
      }), `${target.label}.skillMpCost`);
      track(patchMethod(target.object, "skillTpCost", `${target.label}.skillTpCost`, function (original, args) {
        if (waived(this)) return 0;
        return original.apply(this, args);
      }), `${target.label}.skillTpCost`);
    });
  }

  // --- one-hit kill -----------------------------------------------------------

  function defeatEnemy(battler, source) {
    if (!battler || typeof battler.die !== "function") return false;
    try {
      battler.die();
      bumpBattleStat("oneHitKill", { source });
      return true;
    } catch (_) {
      return false;
    }
  }

  // --- master installer -------------------------------------------------------

  function patchTrainerHooks() {
    const hooked = [];
    const track = (ok, label) => { if (ok) hooked.push(label); };

    hookKeyboard();
    track(patchMoveSpeed(), "moveSpeed");
    track(patchSceneUpdate(), "sceneUpdate");
    track(patchEncounter(), "encounter");
    patchBattleRewards(track);
    patchScaledGain(
      track,
      resolvePrototypeTargets("Game_Actor", ["GameActor"]).concat(partyMemberPrototypeTargets("runtime.party")),
      "gainExp", "expRate", "actorGainExp"
    );
    patchScaledGain(
      track,
      resolvePrototypeTargets("Game_Party", ["GameParty"]),
      "gainGold", "goldRate", "partyGainGold"
    );
    patchDropRate(track);
    patchDamageHooks(track);
    patchVitalsSetters(track);
    patchSkillCost(track);

    bridge.hookTargets = Array.from(new Set(hooked));
    bridge.hooksPatched = hooked.length > 0;
    return { patched: bridge.hooksPatched, count: hooked.length };
  }
  // ---------------------------------------------------------------------------
  // Vitals locks (上帝模式: 无敌 / 锁HP·MP·TP).
  //
  // NOT the same feature as 50-value-locks.js. This one holds a battler's
  // HP/MP/TP through two mechanisms, because neither alone is enough:
  //   1. setHp/setMp/setTp hooks — catch the engine's own writes.
  //   2. a 100ms guard tick — catch plugins that assign `actor._hp` directly.
  // Both honour bridge.suppressLocks so a deliberate trainer write still lands.
  // ---------------------------------------------------------------------------

  // Null means "not locked". lockHpMax tracks the (possibly buffed) max, so it
  // is re-read every time rather than cached.
  function lockedHpValue(battler) {
    if (bridge.options.lockHpMax) return Number(readStat(battler, "mhp", "_mhp")) || 0;
    if (bridge.options.lockHpVal > 0) return bridge.options.lockHpVal;
    return null;
  }

  function lockedVitalValue(option) {
    const value = Number(bridge.options[option]) || 0;
    return value > 0 ? value : null;
  }

  // Shared body of the three setter hooks: rewrite the argument to the locked
  // value instead of blocking the call, so the engine's own bookkeeping
  // (death checks, gauge refresh) still runs.
  function enforceVital(battler, original, args, locked, statName) {
    if (bridge.suppressLocks > 0 || locked == null) return original.apply(battler, args);
    const requested = Number(args[0]);
    if (Number.isFinite(requested) && requested !== locked) {
      bumpBattleStat(statName, { from: requested, to: locked });
      return original.call(battler, locked);
    }
    return original.apply(battler, args);
  }

  function shouldBlockHpDecrease(battler, value) {
    if (bridge.suppressInvincible <= 0 && bridge.options.invincible) {
      // Invincibility is battle-only on purpose: out of battle, HP loss is
      // usually a scripted story beat and blocking it wedges events.
      if (isActorBattler(battler) && isInBattle()) {
        const next = Number(value);
        if (Number.isFinite(next) && next < battlerHp(battler)) return true;
      }
    }
    if (bridge.options.lockHp && isActorBattler(battler)) {
      const locked = lockedHpValue(battler);
      const next = Number(value);
      if (locked != null && Number.isFinite(next) && next < locked) return true;
    }
    return false;
  }

  // --- hooks ------------------------------------------------------------------

  function patchVitalsSetters(track) {
    const targets = uniqueTargets(
      resolvePrototypeTargets("Game_Battler", ["GameBattler"])
        .concat(resolvePrototypeTargets("Game_BattlerBase", ["GameBattlerBase"]))
        .concat(resolvePrototypeTargets("Game_Actor", ["GameActor"]))
        .concat(partyMemberPrototypeTargets("runtime.party"))
    );
    targets.forEach((target) => {
      track(patchMethod(target.object, "setHp", `${target.label}.setHp`, function (original, args) {
        if (shouldBlockHpDecrease(this, args[0])) {
          const keep = bridge.options.lockHp ? lockedHpValue(this) : battlerHp(this);
          bumpBattleStat("invincibleBlockHp", { source: target.label, value: args[0], current: keep });
          return original.call(this, keep);
        }
        if (bridge.options.lockHp && isActorBattler(this)) {
          return enforceVital(this, original, args, lockedHpValue(this), "lockHp");
        }
        return original.apply(this, args);
      }), `${target.label}.setHp`);

      track(patchMethod(target.object, "setMp", `${target.label}.setMp`, function (original, args) {
        if (bridge.options.lockMp && isActorBattler(this)) {
          return enforceVital(this, original, args, lockedVitalValue("lockMpVal"), "lockMp");
        }
        return original.apply(this, args);
      }), `${target.label}.setMp`);

      track(patchMethod(target.object, "setTp", `${target.label}.setTp`, function (original, args) {
        if (bridge.options.lockTp && isActorBattler(this)) {
          return enforceVital(this, original, args, lockedVitalValue("lockTpVal"), "lockTp");
        }
        return original.apply(this, args);
      }), `${target.label}.setTp`);
    });
  }

  // Game_Action.apply is where damage is dealt. Snapshot HP before, restore
  // after: a plugin's custom damage formula may bypass setHp entirely.
  function patchDamageHooks(track) {
    resolvePrototypeTargets("Game_Action", ["GameAction"]).forEach((target) => {
      track(patchMethod(target.object, "apply", `${target.label}.apply`, function (original, args) {
        const subject = typeof this.subject === "function" ? this.subject() : null;
        const targetBattler = args && args[0];
        const hpSnapshot = (bridge.options.invincible || bridge.options.lockHp) && isActorBattler(targetBattler)
          ? battlerHp(targetBattler)
          : null;
        const result = original.apply(this, args);
        if (hpSnapshot != null) restoreLockedHp(targetBattler, hpSnapshot, `${target.label}.apply`);
        if (bridge.options.oneHitKill && isActorBattler(subject) && isEnemyBattler(targetBattler)) {
          defeatEnemy(targetBattler, `${target.label}.apply`);
        }
        return result;
      }), `${target.label}.apply`);

      track(patchMethod(target.object, "executeHpDamage", `${target.label}.executeHpDamage`, function (original, args) {
        const targetBattler = args && args[0];
        const value = Number(args && args[1] || 0);
        const shielded = bridge.options.invincible
          || (bridge.options.lockHp && lockedHpValue(targetBattler) != null);
        if (value > 0 && isActorBattler(targetBattler) && shielded) {
          const next = Array.prototype.slice.call(args);
          next[1] = 0;
          bumpBattleStat("invincibleDamage", { source: target.label, value });
          return original.apply(this, next);
        }
        return original.apply(this, args);
      }), `${target.label}.executeHpDamage`);
    });
  }

  function restoreLockedHp(battler, snapshot, source) {
    if (!isActorBattler(battler) || !Number.isFinite(snapshot)) return false;
    let target = snapshot;
    if (bridge.options.lockHp) {
      const locked = lockedHpValue(battler);
      if (locked != null) target = Math.max(target, locked);
    }
    const current = battlerHp(battler);
    if (current >= target) return false;
    setBattlerHp(battler, target);
    refreshActor(battler);
    bumpBattleStat("lockedHpRestore", { source, from: current, to: target });
    return true;
  }

  // --- guard tick -------------------------------------------------------------

  // MP and TP share one shape; HP does not, because lockHpMax makes its target
  // value dynamic and setBattlerHp has its own fallback path.
  const GUARDED_VITALS = Object.freeze([
    { option: "lockMp", valueOption: "lockMpVal", getter: "mp", field: "_mp", setter: "setMp" },
    { option: "lockTp", valueOption: "lockTpVal", getter: "tp", field: "_tp", setter: "setTp" }
  ]);

  function preserveVitalsTick() {
    try {
      if (bridge.suppressLocks > 0) return;
      partyBattleMembers().forEach((actor) => {
        // Note: invincibility needs no tick — it only ever blocks a decrease,
        // and the setHp/executeHpDamage hooks already cover that.
        if (bridge.options.lockHp) {
          const locked = lockedHpValue(actor);
          if (locked != null && battlerHp(actor) !== locked) setBattlerHp(actor, locked);
        }
        GUARDED_VITALS.forEach((spec) => {
          if (!bridge.options[spec.option]) return;
          const want = lockedVitalValue(spec.valueOption);
          if (want == null) return;
          const current = Number(actor[spec.getter] == null ? actor[spec.field] : actor[spec.getter]) || 0;
          if (current === want) return;
          withLocksSuppressed(() => {
            if (typeof actor[spec.setter] === "function") actor[spec.setter](want);
            else actor[spec.field] = want;
          });
        });
      });
    } catch (error) {
      noteError(error);
    }
  }
  // ---------------------------------------------------------------------------
  // Value locks (数据锁定).
  //
  // NOT the same feature as 45-vitals-locks.js. An arbitrary set of
  // gold/item/switch/variable values, re-asserted once per frame from the
  // SceneManager.updateMain wrapper. The point is to beat the game itself: a
  // shop that charges gold, an event that consumes an item, a script that flips
  // a switch back. The GUI owns persistence (runtime/locks/<gameKey>.json), the
  // bridge owns the live set — so refreshing the GUI never drops a lock.
  //
  // Writes go to the backing store slot (party._items[3] = 99) rather than
  // through gainItem/setValue: this runs 60x a second, and re-entering the
  // game's own hooks that often is both slow and visible (refresh flicker,
  // "item obtained" side effects).
  // ---------------------------------------------------------------------------

  const LOCKABLE_KINDS = Object.freeze(["item", "weapon", "armor", "switch", "variable"]);

  // Locked values are normalised on the way in, once, so the per-frame loop is
  // a plain comparison. lock.set and lock.replace share this.
  function coerceLockValue(kind, value) {
    if (kind === "switch") return !!value;
    if (kind === "variable") return typeof value === "string" ? value : (Number(value) || 0);
    return Math.max(0, Math.floor(Number(value) || 0));
  }

  // Plain-object copy of the live set, safe to serialise over the wire.
  function snapshotValueLocks() {
    const out = { gold: bridge.valueLocks.gold };
    LOCKABLE_KINDS.forEach((kind) => {
      const table = bridge.valueLocks[kind];
      const copy = {};
      for (const id of Object.keys(table)) copy[id] = table[id];
      out[kind] = copy;
    });
    return out;
  }

  function applyValueLocks() {
    const locks = bridge.valueLocks;
    if (!locks || bridge.suppressLocks > 0) return;

    try {
      if (locks.gold != null) {
        const party = resolveParty();
        if (party) party._gold = Math.max(0, Math.floor(locks.gold));
      }

      for (const [kind, prop] of INVENTORY_SLOTS) {
        const table = locks[kind];
        const ids = Object.keys(table);
        if (!ids.length) continue;
        const party = resolveParty();
        const store = party && party[prop];
        if (!store) continue;
        for (const id of ids) {
          const want = Math.max(0, Math.floor(Number(table[id]) || 0));
          if (Number(store[id]) !== want) store[id] = want;
        }
      }

      // Game_Switches/_Variables._data is a sparse array indexed by id.
      writeLockedSlots(locks.switch, resolveSwitches());
      writeLockedSlots(locks.variable, resolveVariables());

      bridge.lockStats.applied += 1;
      bridge.lockStats.lastAt = Date.now();
    } catch (error) {
      bridge.lockStats.errors += 1;
      noteError(error);
    }
  }

  function writeLockedSlots(table, store) {
    const ids = Object.keys(table);
    if (!ids.length) return;
    const data = store && store._data;
    if (!data) return;
    for (const id of ids) {
      if (data[id] !== table[id]) data[id] = table[id];
    }
  }
  // ---------------------------------------------------------------------------
  // Transport. Three channels, one executor.
  //
  //   WebSocket  — primary. The bridge is the CLIENT; the GUI (or `rmch serve`)
  //                hosts 127.0.0.1:47412. Reconnects with exponential backoff,
  //                so closing and reopening the GUI does not require a restart
  //                of the game.
  //   JSONL file — fallback. commands.jsonl in / events.jsonl out, polled every
  //                250ms. Survives a missing server entirely, and is the only
  //                channel available when a game's CSP blocks WebSocket.
  //   CDP outbox — Tauri shells (RMCH_TRANSPORT="cdp"). The page origin is
  //                https://tauri.localhost and Chromium refuses ws:// loopback
  //                from it, so nothing network-shaped can work from here.
  //                Instead outbound messages pile up in window.__rmchOutbox,
  //                which the launcher drains via Runtime.evaluate polling;
  //                inbound commands arrive through window.__rmchDispatch evals.
  //                (Runtime.enable/addBinding are NOT used: this game family's
  //                watchdog kills the process the moment Runtime.enable lands.)
  //
  // All funnel into execute() and all must handle handlers that return a
  // promise (MZ's loadGame does), which is what settleResult exists for.
  // ---------------------------------------------------------------------------

  let ws = null;
  let wsBackoffMs = 1000;
  let wsConnected = false;

  // The transport mode arrives via the env shim (05-node-io reads
  // window.__rmchEnv), so its value doubles as the CDP selector.
  const cdpTransport = transportMode === "cdp";

  function wsUrl() {
    return `ws://127.0.0.1:${wsPort}/bridge/${encodeURIComponent(gameKey)}?token=${encodeURIComponent(wsToken)}`;
  }

  function wsSend(value) {
    if (cdpTransport) {
      try {
        // Drained by the launcher's Runtime.evaluate polling (host side of
        // the CDP link). Entries are JSON strings, joined with \n on drain —
        // JSON.stringify never emits raw newlines, so the framing is safe.
        (window.__rmchOutbox || (window.__rmchOutbox = [])).push(JSON.stringify(value));
        return true;
      } catch (_) {
        return false;
      }
    }
    try {
      if (ws && ws.readyState === 1) {
        ws.send(JSON.stringify(value));
        return true;
      }
    } catch (_) {}
    return false;
  }

  function engineInfo() {
    try {
      const utils = window.Utils || {};
      return {
        maker: utils.RPGMAKER_NAME || null,
        makerVersion: utils.RPGMAKER_VERSION || null,
        title: (window.$dataSystem && window.$dataSystem.gameTitle) || null
      };
    } catch (_) {
      return null;
    }
  }

  // Run a command and report through `reply(ok, payloadOrErrorText)` exactly
  // once, whether the handler threw, returned a value, or returned a promise.
  function settleResult(type, args, reply) {
    let payload;
    try {
      payload = execute(type, args || {});
    } catch (error) {
      // Capture the text BEFORE log(): any file I/O inside log() may set
      // bridge.lastError again (e.g. mkdir quirks on old embedded Node).
      const text = noteError(error);
      log("command failed", { type, error: text });
      reply(false, text);
      return;
    }
    if (payload && typeof payload.then === "function") {
      payload.then(
        (value) => reply(true, value === undefined ? null : value),
        (error) => {
          const text = noteError(error);
          log("command failed (async)", { type, error: text });
          reply(false, text);
        }
      );
      return;
    }
    reply(true, payload === undefined ? null : payload);
  }

  // Shared by the WebSocket onmessage and the CDP __rmchDispatch entry: parse
  // one inbound message and act on it. ping/pong keep WS sessions alive; cmd
  // runs through settleResult and every result triggers a state push.
  function handleIncoming(text) {
    let message = null;
    try {
      message = JSON.parse(text);
    } catch (_) {
      return;
    }
    if (!message || typeof message !== "object") return;
    if (message.t === "ping") {
      wsSend({ t: "pong" });
      return;
    }
    if (message.t !== "cmd") return;
    const id = message.id;
    settleResult(message.type, message.args, (ok, value) => {
      const result = { t: "result", id, ok };
      if (ok) result.payload = value;
      else result.error = value;
      wsSend(result);
      // The GUI treats every result as a chance to re-render live values.
      writeState();
    });
  }

  // --- WebSocket --------------------------------------------------------------

  function connectWs() {
    if (cdpTransport) {
      // No socket at all: outbound piles into window.__rmchOutbox (drained by
      // the launcher's polling), inbound arrives via window.__rmchDispatch
      // (eval'd by the launcher over the same CDP link).
      wsConnected = true;
      window.__rmchDispatch = function (text) {
        handleIncoming(String(text));
      };
      wsSend({
        t: "hello",
        bridgeVersion: bridge.version,
        engine: engineInfo(),
        gameKey,
        profile: bridge.profile || null
      });
      writeState();
      return;
    }
    let socket = null;
    try {
      socket = new WebSocket(wsUrl());
    } catch (error) {
      noteError(error);
      setTimeout(connectWs, wsBackoffMs);
      return;
    }
    ws = socket;

    socket.onopen = function () {
      wsConnected = true;
      wsBackoffMs = 1000;
      wsSend({
        t: "hello",
        bridgeVersion: bridge.version,
        engine: engineInfo(),
        gameKey,
        profile: bridge.profile || null
      });
      writeState();
    };

    socket.onmessage = function (socketEvent) {
      handleIncoming(socketEvent.data);
    };

    socket.onclose = function () {
      wsConnected = false;
      ws = null;
      setTimeout(connectWs, wsBackoffMs);
      wsBackoffMs = Math.min(5000, wsBackoffMs * 2);
    };

    socket.onerror = function () {};
  }

  // --- JSONL file queue (same protocol the zs2/nwr modkits used) -------------

  function hashString(text) {
    let hash = 0;
    for (let index = 0; index < text.length; index += 1) {
      hash = (hash * 31 + text.charCodeAt(index)) | 0;
    }
    return String(hash);
  }

  function commandQueueId(command, line) {
    if (command.commandId) return `file:${command.commandId}`;
    return `file:${hashString(String(line))}`;
  }

  function pollCommands() {
    // No fs (Tauri degraded mode) means no JSONL channel to poll at all.
    if (!fileIo || !commandPath) return;
    try {
      ensureDir();
      if (!fs.existsSync(commandPath)) return;
      const lines = fs.readFileSync(commandPath, "utf8").split(/\r?\n/).filter(Boolean);
      for (const line of lines) {
        let command;
        try {
          command = JSON.parse(line);
        } catch (error) {
          log("bad command json", { line, error: String(error) });
          continue;
        }
        const id = commandQueueId(command, line);
        command.__rmchQueueId = id;
        if (!id || bridge.processed[id]) continue;
        // The file is append-only and never truncated on restart, so anything
        // older than this bridge's start belongs to a previous session.
        if (Number(command.ts || 0) < bridge.startedAtMs) {
          bridge.processed[id] = true;
          continue;
        }
        bridge.processed[id] = true;
        settleResult(command.type, command.args, (ok, value) => {
          event(command, ok, ok ? value : { error: value });
          writeState();
        });
      }
      // Compact the processed map so it never grows unbounded.
      const keys = Object.keys(bridge.processed);
      if (keys.length > 2000) {
        for (let index = 0; index < keys.length - 1000; index += 1) delete bridge.processed[keys[index]];
      }
    } catch (error) {
      log("poll failed", { error: noteError(error) });
    }
  }
  // ---------------------------------------------------------------------------
  // State snapshot: written to state.json every second and pushed over the
  // WebSocket after every command, so the GUI renders live gold / party / map /
  // options without polling the game for each field.
  // ---------------------------------------------------------------------------

  function collectState() {
    const party = resolveParty();
    return {
      bridgeVersion: bridge.version,
      gameKey,
      engine: engineInfo(),
      wsConnected,
      profile: bridge.profile || null,
      startedAt: bridge.startedAt,
      gold: safeGold(party),
      map: currentMapInfo(),
      party: partyBattleMembers().map(actorInfo),
      saveDir: saveDirPath(),
      inBattle: isInBattle(),
      options: { ...bridge.options },
      hooks: {
        patched: bridge.hooksPatched,
        count: bridge.hookTargets.length,
        // Capped: a heavily-plugged game patches hundreds of prototype chain
        // entries and the full list dwarfs the rest of the snapshot.
        targets: bridge.hookTargets.slice(0, 80)
      },
      lastError: bridge.lastError
    };
  }

  function writeState() {
    const state = collectState();
    if (fileIo && statePath) {
      try {
        ensureDir();
        fs.writeFileSync(statePath, JSON.stringify(state, null, 2), "utf8");
      } catch (error) {
        noteError(error);
      }
    }
    wsSend({ t: "state", state });
    return state;
  }
  // ---------------------------------------------------------------------------
  // Commands: core / diagnostics.
  //
  // Every handler takes the args object and returns a plain JSON payload, or
  // throws an Error whose message the GUI shows verbatim. Throwing is the normal
  // way to say "this game does not support that" — see 20-values.js require*.
  // ---------------------------------------------------------------------------

  Object.assign(commandHandlers, {
    "ping": () => collectState(),

    "runtime.info": () => ({
      bridgeVersion: bridge.version,
      engine: engineInfo(),
      gameKey,
      profile: bridge.profile || null,
      hooks: { patched: bridge.hooksPatched, targets: bridge.hookTargets.slice() },
      options: { ...bridge.options },
      location: String(window.location && window.location.href || "")
    }),

    "trainer.options.get": () => ({ options: { ...bridge.options }, hooks: patchTrainerHooks() }),

    // Accepts either {options:{...}} or the option map directly, because the CLI
    // sends the flat form and the GUI sends the wrapped one.
    "trainer.options.set": (args) => ({ options: setTrainerOptions(args.options || args) }),

    "trainer.hooks.info": () => ({
      options: { ...bridge.options },
      hooks: patchTrainerHooks(),
      hookTargets: bridge.hookTargets.slice(),
      rateStats: { ...bridge.rateStats },
      battleStats: { ...bridge.battleStats }
    }),

    // Runs in the page's own realm. Note that on some bundled games the game's
    // globals are not visible to a bare eval (they live in a module scope) —
    // reach them through TK.$ or use the dedicated commands instead.
    "console.eval": (args) => {
      const code = String(args.code || "");
      if (!code.trim()) throw new Error("code is empty");
      const result = (0, eval)(code);
      return { result: compactRuntimeValue(result, 3) };
    }
  });
  // ---------------------------------------------------------------------------
  // Commands: gold, inventory, party, actors.
  //
  // House rule for every mutation here: go through the engine's own method when
  // it exists (gainGold, gainItem, changeLevel) and fall back to the private
  // field only when it does not. The method keeps the game's bookkeeping
  // consistent; the field is the escape hatch for games that removed it.
  // ---------------------------------------------------------------------------

  // Protected games sabotage the engine's own write path (再刷一把 ships
  // gainItem as a native no-op stub) and amplifier plugins scale the delta, so
  // after the polite gainItem call we assert the requested count directly.
  // Equivalent to what gainItem does anyway (container write + map refresh).
  function writeBackItemCount(party, prop, id, want) {
    const store = party[prop];
    if (!store) return;
    const now = Number(store[id]) || 0;
    if (now === want) return;
    if (want > 0) store[id] = want;
    else delete store[id];
    const map = resolveMap();
    if (map && typeof map.requestRefresh === "function") {
      try { map.requestRefresh(); } catch (_) {}
    }
  }

  Object.assign(commandHandlers, {

    // --- gold -----------------------------------------------------------------

    "gold.add": (args) => {
      const party = requireParty();
      const amount = Math.floor(requireNumber(args.amount, "amount"));
      if (typeof party.gainGold === "function") withRatesSuppressed(() => party.gainGold(amount));
      else party._gold = Math.max(0, Number(party._gold || 0) + amount);
      return { gold: safeGold(party) };
    },

    "gold.set": (args) => {
      const party = requireParty();
      const value = Math.max(0, Math.floor(requireNumber(args.value, "value")));
      const current = safeGold(party) || 0;
      // Expressed as a delta so the engine's own clamping/notification runs.
      if (typeof party.gainGold === "function") withRatesSuppressed(() => party.gainGold(value - current));
      else party._gold = value;
      return { gold: safeGold(party) };
    },

    // --- catalogs -------------------------------------------------------------

    "catalog.query": (args) => {
      const kind = String(args.kind || "");
      if (!CATALOG_KINDS.includes(kind)) throw new Error(`unsupported catalog kind: ${kind}`);
      return catalogEntries(kind, { query: args.query, limit: clampNumber(args.limit, 1, 2000, 500) });
    },

    // --- inventory ------------------------------------------------------------

    "item.add": (args) => {
      const party = requireParty("gainItem");
      const kind = normalizeDropKind(args.kind || "item");
      if (!kind) throw new Error(`unsupported item kind: ${args.kind}`);
      const { id } = requireDataEntry(kind, args.id, "id");
      const amount = Math.floor(requireNumber(args.amount, "amount"));
      if (!Number.isFinite(amount) || amount === 0) throw new Error("amount must be a non-zero number");
      const prop = inventorySlot(kind);
      const want = Math.max(0, (Number(party[prop] && party[prop][id]) || 0) + amount);
      withRatesSuppressed(() => party.gainItem(runtimeDataTable(kind)[id], amount));
      writeBackItemCount(party, prop, id, want);
      return { kind, id, amount, count: Number(party[prop] && party[prop][id]) || 0 };
    },

    // MTool-style inventory view: everything the party currently owns, with counts.
    "item.list": () => {
      const party = requireParty();
      const entries = [];
      for (const [kind, prop] of INVENTORY_SLOTS) {
        const store = party[prop];
        if (!store) continue;
        for (const key of Object.keys(store)) {
          // Counts are integers by engine contract; amplifier plugins in some
          // games stash fractions (2.5 件装备) in the container. Rounding here
          // is display-only — the in-memory value is left untouched.
          const count = Math.round(Number(store[key]) || 0);
          if (count <= 0) continue;
          const id = Number(key);
          const entry = runtimeDataTable(kind)[id];
          entries.push({ kind, id, name: entry && entry.name || "", count });
        }
      }
      entries.sort((a, b) => (a.kind === b.kind ? a.id - b.id : a.kind.localeCompare(b.kind)));
      return { entries };
    },

    "item.set": (args) => {
      const party = requireParty("gainItem");
      const kind = normalizeDropKind(args.kind || "item");
      if (!kind) throw new Error(`unsupported item kind: ${args.kind}`);
      const { id } = requireDataEntry(kind, args.id, "id");
      const count = Math.max(0, Math.floor(requireNumber(args.count, "count")));
      const prop = inventorySlot(kind);
      const current = Number(party[prop] && party[prop][id]) || 0;
      const delta = count - current;
      // gainItem first so a working engine keeps its bookkeeping; the writeback
      // then pins the exact count when gainItem is stubbed or scaled.
      if (delta !== 0) withRatesSuppressed(() => party.gainItem(runtimeDataTable(kind)[id], delta));
      writeBackItemCount(party, prop, id, count);
      return { kind, id, count: Number(party[prop] && party[prop][id]) || 0 };
    },

    // --- party ----------------------------------------------------------------

    "party.info": () => {
      const party = resolveParty();
      return {
        gold: safeGold(party),
        members: getPartyMembers(party).map(actorInfo),
        battleMembers: partyBattleMembers().map(actorInfo),
        maxBattleMembers: party && party.maxBattleMembers != null ? safeCall(() => party.maxBattleMembers()) : null
      };
    },

    "party.recover": () => {
      const members = getPartyMembers(resolveParty());
      members.forEach((actor) => {
        if (typeof actor.recoverAll === "function") actor.recoverAll();
        else {
          withLocksSuppressed(() => {
            setBattlerHp(actor, Number(readStat(actor, "mhp", "_mhp")) || 9999);
            if (typeof actor.setMp === "function") actor.setMp(Number(readStat(actor, "mmp", "_mmp")) || 9999);
          });
        }
        refreshActor(actor);
      });
      refreshMapAndWindows();
      return { recovered: members.length, members: members.map(actorInfo) };
    },

    "party.addActor": (args) => {
      const party = requireParty("addActor");
      const { id } = requireDataEntry("actor", args.id, "actor id");
      party.addActor(id);
      refreshMapAndWindows();
      return { id, actor: actorInfo(requireActor(id)) };
    },

    "party.removeActor": (args) => {
      const party = requireParty("removeActor");
      const id = Math.floor(requireNumber(args.id, "id"));
      party.removeActor(id);
      refreshMapAndWindows();
      return { id };
    },

    // --- actors ---------------------------------------------------------------

    "actor.info": (args) => ({ actor: actorInfo(requireActor(requireNumber(args.id, "id"))) }),

    "actor.recover": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      if (typeof actor.recoverAll === "function") actor.recoverAll();
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor) };
    },

    "actor.level.set": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      let maxLevel = 999;
      try {
        if (typeof actor.maxLevel === "function") maxLevel = Math.max(1, Math.floor(Number(actor.maxLevel() || maxLevel)));
      } catch (_) {}
      const level = Math.min(maxLevel, Math.max(1, Math.floor(requireNumber(args.level, "level"))));
      // changeLevel(level, false) = no level-up message spam.
      if (typeof actor.changeLevel === "function") actor.changeLevel(level, false);
      else actor._level = level;
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor) };
    },

    "actor.exp.add": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const amount = Math.floor(requireNumber(args.amount, "amount"));
      if (typeof actor.gainExp === "function") withRatesSuppressed(() => actor.gainExp(amount));
      else if (typeof actor.changeExp === "function" && typeof actor.currentExp === "function") {
        actor.changeExp(actor.currentExp() + amount, false);
      } else {
        actor._exp = actor._exp || {};
        const classId = actor._classId || 0;
        actor._exp[classId] = Number(actor._exp[classId] || 0) + amount;
      }
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor), amount };
    },

    "actor.vitals.set": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      // Vitals locks would immediately undo these writes, hence the suppression.
      const write = (value, max, fallbackMax, setter, field) => {
        if (!hasValue(value)) return;
        const next = clampCurrentValue(value, max, fallbackMax);
        withLocksSuppressed(() => {
          if (typeof actor[setter] === "function") actor[setter](next);
          else actor[field] = next;
        });
      };
      write(args.hp, readStat(actor, "mhp", "_mhp"), 999999999, "setHp", "_hp");
      write(args.mp, readStat(actor, "mmp", "_mmp"), 999999999, "setMp", "_mp");
      write(args.tp, 100, 100, "setTp", "_tp");
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor) };
    },

    "actor.param.add": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const paramId = Math.floor(requireNumber(args.paramId, "paramId"));
      if (paramId < 0 || paramId > 7) throw new Error("paramId must be between 0 and 7");
      const value = Math.floor(requireNumber(args.value, "value"));
      if (typeof actor.addParam === "function") actor.addParam(paramId, value);
      else {
        actor._paramPlus = actor._paramPlus || [0, 0, 0, 0, 0, 0, 0, 0];
        actor._paramPlus[paramId] = Number(actor._paramPlus[paramId] || 0) + value;
      }
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor), paramId, value };
    },

    "actor.name.set": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const name = String(args.name || "");
      if (typeof actor.setName === "function") actor.setName(name);
      else actor._name = name;
      refreshMapAndWindows();
      return { actor: actorInfo(actor) };
    },

    "actor.nickname.set": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const nickname = String(args.nickname == null ? "" : args.nickname);
      if (typeof actor.setNickname === "function") actor.setNickname(nickname);
      else actor._nickname = nickname;
      refreshMapAndWindows();
      return { actor: actorInfo(actor) };
    },

    "actor.class.set": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const classId = Math.floor(requireNumber(args.classId, "classId"));
      if (typeof actor.changeClass !== "function") throw new Error("actor.changeClass is unavailable");
      actor.changeClass(classId, args.keepExp !== false);
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor) };
    },

    "actor.skill.learn": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const { id: skillId } = requireDataEntry("skill", args.skillId, "skillId");
      if (typeof actor.learnSkill !== "function") throw new Error("actor learnSkill is unavailable");
      actor.learnSkill(skillId);
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor), skillId };
    },

    "actor.skill.forget": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const { id: skillId } = requireDataEntry("skill", args.skillId, "skillId");
      if (typeof actor.forgetSkill !== "function") throw new Error("actor forgetSkill is unavailable");
      actor.forgetSkill(skillId);
      refreshActor(actor);
      refreshMapAndWindows();
      return { actor: actorInfo(actor), skillId };
    },

    "actor.state.add": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const stateId = Math.floor(requireNumber(args.stateId, "stateId"));
      if (typeof actor.addState !== "function") throw new Error("actor.addState is unavailable");
      actor.addState(stateId);
      refreshActor(actor);
      return { actor: actorInfo(actor) };
    },

    "actor.state.remove": (args) => {
      const actor = requireActor(requireNumber(args.id, "id"));
      const stateId = Math.floor(requireNumber(args.stateId, "stateId"));
      if (typeof actor.removeState !== "function") throw new Error("actor.removeState is unavailable");
      actor.removeState(stateId);
      refreshActor(actor);
      return { actor: actorInfo(actor) };
    }
  });
  // ---------------------------------------------------------------------------
  // Commands: switches, variables, maps, events, battle.
  //
  // Switch/variable ids are validated against $dataSystem's declared length:
  // writing past it "works" but the game never reads it back, which looks like
  // the trainer silently failing.
  // ---------------------------------------------------------------------------

  const SELF_SWITCH_LETTERS = Object.freeze(["A", "B", "C", "D"]);

  function requireSystemId(kind, value, label) {
    const id = requireId(value, label);
    const limit = systemListLimit(kind);
    if (limit > 0 && id >= limit) throw new Error(`${label} ${id} exceeds system limit ${limit}`);
    return id;
  }

  Object.assign(commandHandlers, {

    // --- switches / variables -------------------------------------------------

    "switch.set": (args) => {
      const switches = requireSwitches();
      const id = requireSystemId("switches", args.id, "switch id");
      switches.setValue(id, !!args.value);
      return { id, value: !!args.value };
    },

    "switch.list": (args) => listSystemEntries("switches", args),

    "variable.set": (args) => {
      const variables = requireVariables();
      const id = requireSystemId("variables", args.id, "variable id");
      variables.setValue(id, args.value);
      return { id, value: args.value };
    },

    "variable.list": (args) => listSystemEntries("variables", args),

    // --- self switches --------------------------------------------------------
    //
    // Keyed by [mapId, eventId, letter] and stored sparsely: only switches that
    // have ever been set exist, so the list is "what this map has touched", not
    // "every event on this map".

    "selfSwitch.set": (args) => {
      const selfSwitches = requireSelfSwitches();
      const mapId = Math.floor(requireNumber(args.mapId, "mapId"));
      const eventId = Math.floor(requireNumber(args.eventId, "eventId"));
      const letter = String(args.letter || "A").toUpperCase();
      if (!SELF_SWITCH_LETTERS.includes(letter)) throw new Error("letter must be one of A/B/C/D");
      selfSwitches.setValue([mapId, eventId, letter], !!args.value);
      return { mapId, eventId, letter, value: !!args.value };
    },

    "selfSwitch.list": (args) => {
      const selfSwitches = resolveSelfSwitches();
      const mapId = Math.floor(requireNumber(args.mapId, "mapId"));
      const entries = [];
      try {
        const data = selfSwitches && selfSwitches._data;
        if (data) {
          Object.keys(data).forEach((key) => {
            const parts = String(key).split(",");
            if (Number(parts[0]) !== mapId) return;
            entries.push({
              mapId: Number(parts[0]),
              eventId: Number(parts[1]),
              letter: parts[2] || "",
              value: !!data[key]
            });
          });
        }
      } catch (_) {}
      return { mapId, entries };
    },

    // --- maps / movement ------------------------------------------------------

    "map.info": () => currentMapInfo(),
    "map.list": () => mapList(),

    "map.transfer": (args) => {
      const player = requirePlayer();
      const mapId = requireId(args.mapId, "mapId");
      const mapInfoTable = runtimeDataTable("mapInfo");
      // Only validate when the table is actually loaded — an early transfer
      // request should not be rejected just because $dataMapInfos is still empty.
      if (Array.isArray(mapInfoTable) && mapInfoTable.length > 1 && !mapInfoTable[mapId]) {
        throw new Error(`map ${mapId} not found`);
      }
      const x = Math.floor(requireNumber(args.x, "x"));
      const y = Math.floor(requireNumber(args.y, "y"));
      const direction = hasValue(args.direction) ? Math.floor(requireNumber(args.direction, "direction")) : 2;
      const fade = hasValue(args.fade) ? Math.floor(requireNumber(args.fade, "fade")) : 0;
      if (typeof player.reserveTransfer === "function") {
        player.reserveTransfer(mapId, x, y, direction, fade);
      } else if (typeof player.locate === "function") {
        player.locate(x, y);
      } else {
        throw new Error("player transfer is unavailable");
      }
      refreshMapAndWindows();
      return { mapId, x, y, direction, fade };
    },

    "map.through.set": (args) => {
      const player = requireThroughCapablePlayer();
      player._through = !!args.value;
      bridge.options.throughWalls = player._through;
      return { through: player._through };
    },

    "map.through.toggle": () => {
      const player = requireThroughCapablePlayer();
      player._through = !player._through;
      bridge.options.throughWalls = player._through;
      return { through: player._through };
    },

    "player.location": () => {
      const player = requirePlayer();
      return {
        mapId: player._mapId != null ? player._mapId : (resolveMap() && resolveMap()._mapId),
        x: player._x,
        y: player._y,
        direction: player._direction
      };
    },

    // --- map events -----------------------------------------------------------

    "map.events.list": () => {
      const map = requireMap();
      const events = Array.isArray(map._events) ? map._events : [];
      const entries = [];
      events.forEach((mapEvent) => {
        if (!mapEvent) return;
        let data = null;
        try { data = typeof mapEvent.event === "function" ? mapEvent.event() : null; } catch (_) {}
        let commands = 0;
        try {
          const page = data && data.pages && data.pages[mapEvent._pageIndex];
          commands = page && Array.isArray(page.list) ? page.list.length : 0;
        } catch (_) {}
        entries.push({
          eventId: Number(mapEvent._eventId) || 0,
          name: (data && data.name) || "",
          x: Number(mapEvent._x) || 0,
          y: Number(mapEvent._y) || 0,
          pageIndex: mapEvent._pageIndex == null ? null : Number(mapEvent._pageIndex),
          pages: (data && Array.isArray(data.pages)) ? data.pages.length : 0,
          commands
        });
      });
      entries.sort((a, b) => a.eventId - b.eventId);
      return { mapId: typeof map.mapId === "function" ? map.mapId() : null, entries };
    },

    "map.transferToEvent": (args) => {
      const map = requireMap();
      const player = requirePlayer();
      const eventId = Math.floor(requireNumber(args.eventId, "eventId"));
      const mapEvent = typeof map.event === "function" ? map.event(eventId) : null;
      if (!mapEvent) throw new Error(`event ${eventId} is not on the current map`);
      const x = Number(mapEvent._x) || 0;
      const y = Number(mapEvent._y) || 0;
      if (typeof player.locate === "function") player.locate(x, y);
      else { player._x = x; player._y = y; }
      return { eventId, x, y };
    },

    "commonEvent.run": (args) => {
      const id = Math.floor(requireNumber(args.id, "id"));
      const eventData = runtimeDataTable("commonEvent")[id];
      if (!eventData) throw new Error(`common event ${id} not found`);
      const temp = requireEngineObject(resolveTemp(), "game temp", "reserveCommonEvent");
      temp.reserveCommonEvent(id);
      const map = resolveMap();
      if (map && typeof map.requestRefresh === "function") map.requestRefresh();
      return { id, name: eventData.name || "" };
    },

    // --- battle ---------------------------------------------------------------

    "battle.info": () => ({
      inBattle: isInBattle(),
      enemies: troopEnemies(false).map((enemy, index) => ({
        index,
        name: enemyNameOf(enemy),
        hp: battlerHp(enemy),
        mhp: Number(readStat(enemy, "mhp", "_mhp")) || null,
        isAlive: typeof enemy.isAlive === "function" ? !!enemy.isAlive() : battlerHp(enemy) > 0
      })),
      party: partyBattleMembers().map(actorInfo)
    }),

    "battle.enemy.setHp": (args) => {
      const index = Math.floor(requireNumber(args.index, "index"));
      const enemy = troopEnemies(false)[index];
      if (!enemy) throw new Error(`enemy index ${index} not found`);
      const hp = Math.max(0, Math.floor(requireNumber(args.value, "value")));
      withLocksSuppressed(() => {
        if (typeof enemy.setHp === "function") enemy.setHp(hp);
        else enemy._hp = hp;
      });
      return { index, hp: battlerHp(enemy) };
    },

    "battle.killEnemies": () => {
      let killed = 0;
      troopEnemies(true).forEach((enemy) => {
        if (defeatEnemy(enemy, "battle.killEnemies")) killed += 1;
      });
      return { killed, remaining: troopEnemies(true).length };
    },

    "battle.escape": () => {
      const managers = resolveBattleManagers();
      const battle = managers[0] && managers[0].object;
      if (!battle) throw new Error("battle manager is unavailable");
      if (!isInBattle()) throw new Error("not in battle");
      // abortBattle is the clean exit; endBattle(1) is the "escaped" result code
      // and is what older/patched managers expose instead.
      if (typeof battle.abortBattle === "function") {
        battle.abortBattle();
        return { escaped: true, method: "abortBattle" };
      }
      if (typeof battle.endBattle === "function") {
        battle.endBattle(1);
        return { escaped: true, method: "endBattle" };
      }
      throw new Error("no escape method available");
    }
  });

  // Some games strip _through entirely; failing loudly beats setting a field the
  // engine never reads.
  function requireThroughCapablePlayer() {
    const player = requirePlayer();
    if (!Object.prototype.hasOwnProperty.call(player, "_through")) {
      throw new Error("player through field is unavailable");
    }
    return player;
  }
  // ---------------------------------------------------------------------------
  // Commands: save slots, the runtime save-data tree, value locks.
  //
  // save.contents.* is the 数据修改 feature: the live save contents serialised
  // the way the game itself would write a save, edited as a JSON tree in the
  // GUI, then handed back. JsonEx (not JSON) so class identity survives the
  // round trip — its output is still valid JSON, which is what makes the tree
  // editor possible at all.
  // ---------------------------------------------------------------------------

  Object.assign(commandHandlers, {

    // --- save slots -----------------------------------------------------------

    "save.list": () => {
      const dir = saveDirPath();
      const entries = [];
      try {
        for (const name of fs.readdirSync(dir)) {
          // MV writes fileN.rpgsave, MZ writes fileN.rmmzsave.
          if (!/\.(rpgsave|rmmzsave)$/i.test(name)) continue;
          const stat = fs.statSync(path.join(dir, name));
          entries.push({ name, size: stat.size, mtime: stat.mtime.toISOString() });
        }
      } catch (_) {}
      entries.sort((a, b) => a.name.localeCompare(b.name));
      return { dir, entries };
    },

    "save.save": (args) => {
      const id = requireId(args.id === undefined ? 1 : args.id, "save id");
      const dataManager = requireDataManager("saveGame");
      if (!dataManager.saveGame(id)) throw new Error("saveGame returned false");
      // Without global info the title screen's slot list stays stale.
      try {
        if (typeof dataManager.saveGlobalInfo === "function") dataManager.saveGlobalInfo();
      } catch (_) {}
      return { id, saved: true };
    },

    "save.load": (args) => {
      const id = requireId(args.id, "save id");
      const dataManager = requireDataManager("loadGame");
      // MV returns a boolean synchronously; MZ returns a promise. Either way the
      // game's own (possibly patched) StorageManager handles the file format.
      const loaded = dataManager.loadGame(id);
      const enterMap = (ok) => {
        if (!ok) throw new Error(`loadGame(${id}) failed`);
        try {
          const system = resolveSystem();
          if (system && typeof system.onAfterLoad === "function") system.onAfterLoad();
        } catch (_) {}
        const sceneManager = resolveSceneManager();
        const sceneMap = resolveSceneMap();
        if (sceneManager && typeof sceneManager.goto === "function" && sceneMap) sceneManager.goto(sceneMap);
        return { id, loaded: true };
      };
      return loaded && typeof loaded.then === "function" ? loaded.then(enterMap) : enterMap(loaded);
    },

    // --- save-data tree (数据修改) --------------------------------------------

    "save.contents.get": (args) => {
      const dataManager = requireDataManager("makeSaveContents");
      const jsonEx = requireJsonEx("stringify");
      const contents = dataManager.makeSaveContents();
      // JsonEx.maxDepth defaults to 100; deep plugin structures otherwise throw.
      const previousDepth = jsonEx.maxDepth;
      let json;
      try {
        jsonEx.maxDepth = Math.max(Number(previousDepth) || 100, 200);
        json = jsonEx.stringify(contents);
      } finally {
        jsonEx.maxDepth = previousDepth;
      }
      const bytes = json.length;
      // A 40MB save would wedge the tree editor; make the refusal explicit and
      // let the caller raise the ceiling deliberately.
      const limit = Math.max(1, Math.floor(Number(args && args.limitBytes) || 12 * 1024 * 1024));
      if (bytes > limit) {
        throw new Error(`save contents is ${bytes} bytes, over the ${limit} byte limit — ` +
          "raise limitBytes if you really want to load it into the editor");
      }
      return { json, bytes, keys: Object.keys(contents || {}) };
    },

    "save.contents.apply": (args) => {
      const dataManager = requireDataManager("extractSaveContents");
      const jsonEx = requireJsonEx("parse");
      const json = String(args.json || "");
      if (!json.trim()) throw new Error("json is empty");
      const contents = jsonEx.parse(json);
      if (!contents || typeof contents !== "object") throw new Error("parsed contents is not an object");

      // extractSaveContents swaps every $game* global at once, so the running
      // scene is left holding stale references; reload the map the same way
      // Scene_Load does unless the caller opts out.
      dataManager.extractSaveContents(contents);
      let reloaded = false;
      if (args.reload !== false) {
        try {
          const player = resolvePlayer();
          const map = resolveMap();
          const sceneManager = resolveSceneManager();
          const sceneMap = resolveSceneMap();
          if (player && map && typeof player.reserveTransfer === "function") {
            player.reserveTransfer(map.mapId(), player.x, player.y,
              typeof player.direction === "function" ? player.direction() : 2, 0);
            if (typeof player.requestMapReload === "function") player.requestMapReload();
          }
          if (sceneManager && sceneMap && typeof sceneManager.goto === "function") {
            sceneManager.goto(sceneMap);
            reloaded = true;
          }
        } catch (error) {
          noteError(error);
        }
      }
      return { applied: true, reloaded, bytes: json.length };
    },

    // --- value locks (数据锁定) ----------------------------------------------

    "lock.list": () => ({ locks: snapshotValueLocks(), stats: { ...bridge.lockStats } }),

    "lock.set": (args) => {
      const kind = String(args.kind || "");
      if (kind === "gold") {
        bridge.valueLocks.gold = args.enabled === false
          ? null
          : Math.max(0, Math.floor(requireNumber(args.value, "value")));
        return { kind, enabled: bridge.valueLocks.gold != null, value: bridge.valueLocks.gold };
      }
      const table = bridge.valueLocks[kind];
      if (!table) throw new Error(`unsupported lock kind: ${kind}`);
      const id = Math.floor(requireNumber(args.id, "id"));
      if (args.enabled === false) {
        delete table[id];
        return { kind, id, enabled: false, value: null };
      }
      const value = coerceLockValue(kind, args.value);
      table[id] = value;
      return { kind, id, enabled: true, value };
    },

    "lock.clear": (args) => {
      const kind = args && args.kind ? String(args.kind) : null;
      if (!kind) {
        bridge.valueLocks.gold = null;
        LOCKABLE_KINDS.forEach((key) => { bridge.valueLocks[key] = Object.create(null); });
        return { cleared: "all", locks: snapshotValueLocks() };
      }
      if (kind === "gold") bridge.valueLocks.gold = null;
      else if (bridge.valueLocks[kind]) bridge.valueLocks[kind] = Object.create(null);
      else throw new Error(`unsupported lock kind: ${kind}`);
      return { cleared: kind, locks: snapshotValueLocks() };
    },

    // Bulk restore, used when the GUI reconnects and replays a saved lock set.
    "lock.replace": (args) => {
      const incoming = args.locks || {};
      LOCKABLE_KINDS.forEach((kind) => {
        const table = Object.create(null);
        const source = incoming[kind];
        if (source && typeof source === "object") {
          for (const key of Object.keys(source)) {
            const id = Math.floor(Number(key));
            if (!Number.isFinite(id)) continue;
            table[id] = coerceLockValue(kind, source[key]);
          }
        }
        bridge.valueLocks[kind] = table;
      });
      bridge.valueLocks.gold = incoming.gold == null
        ? null
        : Math.max(0, Math.floor(Number(incoming.gold) || 0));
      return { locks: snapshotValueLocks() };
    }
  });
  // ---------------------------------------------------------------------------
  // Commands: decoded game assets.
  //
  // The GUI slices item/skill/state icons out of the game's IconSet sheet. On
  // disk that file is often unreadable — MV encryption (.rpgmvp) or custom
  // asset protection — so this command asks the running game for the DECODED
  // sheet instead: whatever loader/decrypter pipeline the game ships with has
  // already produced plaintext pixels by the time they hit a Bitmap.
  // ---------------------------------------------------------------------------

  Object.assign(commandHandlers, {

    // Pull the decoded IconSet sheet as a data URL. Async: the image may still
    // be decoding when loadSystem returns, so poll isReady() on a deadline.
    "assets.iconset": () => {
      const imageManager = resolveImageManager();
      if (!imageManager || typeof imageManager.loadSystem !== "function") {
        throw new Error("ImageManager unavailable — not an MV/MZ game?");
      }
      let bitmap;
      try {
        bitmap = imageManager.loadSystem("IconSet");
      } catch (error) {
        throw new Error(`loadSystem("IconSet") failed: ${error.message}`);
      }
      if (!bitmap) throw new Error('loadSystem("IconSet") returned nothing');

      const deadline = Date.now() + 8000;
      return new Promise((resolve, reject) => {
        const tick = () => {
          let ready = false;
          try {
            ready = typeof bitmap.isReady === "function"
              ? bitmap.isReady()
              : !!(bitmap._image || bitmap._canvas);
          } catch (_) {}
          if (!ready) {
            if (Date.now() > deadline) {
              reject(new Error("timed out waiting for the game to decode IconSet"));
              return;
            }
            setTimeout(tick, 120);
            return;
          }
          // MV draws odd-sized images into _canvas; MZ keeps the decoded
          // HTMLImageElement in _image. Take whichever holds pixels.
          const source = (bitmap._canvas && bitmap._canvas.width) ? bitmap._canvas
            : (bitmap._image && bitmap._image.width) ? bitmap._image : null;
          if (!source) {
            reject(new Error("IconSet bitmap reports ready but has no decoded pixels"));
            return;
          }
          try {
            const canvas = document.createElement("canvas");
            canvas.width = source.width;
            canvas.height = source.height;
            canvas.getContext("2d").drawImage(source, 0, 0);
            resolve({
              dataUrl: canvas.toDataURL("image/png"),
              width: source.width,
              height: source.height
            });
          } catch (error) {
            reject(new Error(`IconSet canvas export failed: ${error.message}`));
          }
        };
        tick();
      });
    }
  });
  // ---------------------------------------------------------------------------
  // Commands: scene navigation and recovery.
  //
  // These exist because a trainer breaks games. Forcing a switch mid-cutscene
  // leaves the interpreter waiting forever; a bad transfer leaves the screen
  // faded out. 修复错误 is the "get me moving again" toolbox, and it deliberately
  // uses the engine's own clear/goto paths rather than reconstructing state.
  // ---------------------------------------------------------------------------

  // Scenes worth pushing from the trainer. Filtered at call time to the ones
  // this game actually defines: MZ drops some, plugins add others.
  const PUSHABLE_SCENES = Object.freeze([
    "Scene_Item", "Scene_Skill", "Scene_Equip", "Scene_Status", "Scene_Menu",
    "Scene_Save", "Scene_Load", "Scene_Options", "Scene_Debug", "Scene_Shop",
    "Scene_Name", "Scene_GameEnd"
  ]);

  function availableScenes() {
    return PUSHABLE_SCENES.filter((name) => typeof window[name] === "function");
  }

  // action -> handler. A table rather than a switch so `game.repair` can report
  // the supported set, and adding one is a single entry.
  const REPAIR_ACTIONS = Object.freeze({
    clearPictures: () => {
      const screen = requireEngineObject(resolveScreen(), "Game_Screen", "clearPictures");
      screen.clearPictures();
    },

    // Clears the map interpreter and every event's own interpreter: a stuck
    // "wait for movement" on one event blocks the whole map.
    clearCurrentEvent: () => {
      const map = requireMap();
      const interpreter = map._interpreter;
      if (!interpreter || typeof interpreter.clear !== "function") {
        throw new Error("map interpreter is unavailable");
      }
      interpreter.clear();
      if (map._events) {
        map._events.forEach((mapEvent) => {
          try {
            if (mapEvent && mapEvent._interpreter && typeof mapEvent._interpreter.clear === "function") {
              mapEvent._interpreter.clear();
            }
          } catch (_) {}
        });
      }
    },

    clearMoveRoute: () => {
      const player = requirePlayer("forceMoveRoute");
      if (typeof player.processRouteEnd === "function") player.processRouteEnd();
      player._moveRouteForcing = false;
      player._waitCount = 0;
    },

    // Also clears the interpreter's wait mode: a fade-out usually comes paired
    // with a wait the script never releases.
    fadeIn: () => {
      const screen = resolveScreen();
      const map = resolveMap();
      if (screen && typeof screen.startFadeIn === "function") screen.startFadeIn(24);
      if (map && map._interpreter) map._interpreter._waitMode = "";
    },

    gotoTitle: () => {
      const sceneManager = requireSceneManager("goto");
      if (typeof window.Scene_Title !== "function") throw new Error("Scene_Title is unavailable");
      sceneManager.goto(window.Scene_Title);
    },

    gotoMap: () => {
      const sceneManager = requireSceneManager("goto");
      const sceneMap = resolveSceneMap();
      if (!sceneMap) throw new Error("Scene_Map is unavailable");
      sceneManager.goto(sceneMap);
    }
  });

  Object.assign(commandHandlers, {

    // --- scenes ---------------------------------------------------------------

    "scene.info": () => {
      const sceneManager = resolveSceneManager();
      const scene = sceneManager && sceneManager._scene;
      const stack = sceneManager && Array.isArray(sceneManager._stack) ? sceneManager._stack : [];
      return {
        current: scene && scene.constructor && scene.constructor.name || null,
        stackDepth: stack.length,
        available: availableScenes()
      };
    },

    "scene.push": (args) => {
      const name = String(args.name || "");
      // Whitelisted: pushing an arbitrary window global would be a crash
      // generator, and the GUI only ever offers what scene.info reported.
      if (!availableScenes().includes(name)) {
        throw new Error(`scene is unavailable: ${name || "(empty)"}`);
      }
      requireSceneManager("push").push(window[name]);
      return { pushed: name };
    },

    "scene.pop": () => {
      requireSceneManager("pop").pop();
      return { popped: true };
    },

    // --- repair (修复错误) ----------------------------------------------------

    "game.repair": (args) => {
      const action = String(args.action || "");
      const handler = REPAIR_ACTIONS[action];
      if (!handler) {
        throw new Error(`unsupported repair action: ${action || "(empty)"} ` +
          `(supported: ${Object.keys(REPAIR_ACTIONS).join(", ")})`);
      }
      handler();
      return { action, done: true };
    },

    "game.newGame": () => {
      const dataManager = requireDataManager("setupNewGame");
      const sceneManager = requireSceneManager("goto");
      const sceneMap = resolveSceneMap();
      if (!sceneMap) throw new Error("Scene_Map is unavailable");
      dataManager.setupNewGame();
      sceneManager.goto(sceneMap);
      return { started: true };
    }
  });
  // ---------------------------------------------------------------------------
  // Router. Every 6x-commands-*.js part has assigned its domain onto
  // commandHandlers by now; freeze it so a profile can extend the bridge but
  // never silently replace a core command.
  // ---------------------------------------------------------------------------

  Object.freeze(commandHandlers);

  function execute(type, args) {
    const key = String(type || "");
    // Core first, profile second: a per-game profile adds commands, it does not
    // shadow them. (profileCommands is declared in 70-profiles.js — this only
    // runs after every part has loaded.)
    const handler = commandHandlers[key] || profileCommands[key];
    if (!handler) throw new Error(`unknown command type: ${type}`);
    return handler(args || {});
  }
  // ---------------------------------------------------------------------------
  // Per-game profiles: optional JS files at
  // <projectRoot>/runtime/bridge/profiles/<gameKey>.js that extend the generic
  // bridge with game-specific commands and options. They run in the page
  // context with the API object below; the generic core never depends on them,
  // and a profile that throws must not take the bridge down with it.
  // ---------------------------------------------------------------------------

  const profileCommands = Object.create(null);

  function profileApi() {
    return {
      bridge,
      registerCommands(handlers) {
        if (handlers && typeof handlers === "object") Object.assign(profileCommands, handlers);
      },
      registerOptions(defaults) {
        if (defaults && typeof defaults === "object") Object.assign(bridge.options, defaults);
      },
      patchMethod,
      setTrainerOptions,
      patchTrainerHooks,
      resolve: {
        party: resolveParty,
        system: resolveSystem,
        variables: resolveVariables,
        switches: resolveSwitches,
        selfSwitches: resolveSelfSwitches,
        actors: resolveActors,
        troop: resolveTroop,
        temp: resolveTemp,
        map: resolveMap,
        player: resolvePlayer,
        followers: resolveFollowers,
        screen: resolveScreen,
        dataManager: resolveDataManager,
        storageManager: resolveStorageManager,
        data: resolveData,
        battleManagers: resolveBattleManagers
      },
      helpers: {
        actorInfo,
        actorIdOf,
        requireActor,
        getPartyMembers,
        partyBattleMembers,
        troopEnemies,
        battlerHp,
        setBattlerHp,
        refreshActor,
        refreshMapAndWindows,
        currentMapInfo,
        catalogEntries,
        runtimeDataTable,
        // Suppression scopes: wrap a write so the trainer's own hooks leave it
        // alone. See 20-values.js for which hook honours which.
        withRatesSuppressed,
        withLocksSuppressed,
        withNoCostSuppressed,
        withInvincibleSuppressed,
        clampNumber,
        looseNumber,
        requireNumber,
        toBool,
        log,
        event
      },
      paths: { gameRoot, projectRoot, bridgeDir },
      fs,
      path
    };
  }

  function loadProfile() {
    // Profiles are read from disk; in a no-Node shell (Tauri) there are none.
    if (!fileIo) {
      bridge.profile = { loaded: false, reason: "no fs in page context" };
      return false;
    }
    try {
      const profilePath = path.join(projectRoot, "runtime", "bridge", "profiles", `${gameKey}.js`);
      if (!fs.existsSync(profilePath)) {
        bridge.profile = { loaded: false, reason: "no profile" };
        return false;
      }
      const source = fs.readFileSync(profilePath, "utf8");
      const api = profileApi();
      // One execution covers both profile forms: a plain script that uses the
      // api directly, and `module.exports = function (api) {...}` (the export is
      // invoked after the runner so the body sees the same api object).
      const moduleObject = { exports: {} };
      const runner = new Function("api", "module", "exports", `"use strict";\n${source}\n`);
      runner(api, moduleObject, moduleObject.exports);
      const exported = moduleObject.exports;
      const entry = typeof exported === "function"
        ? exported
        : (exported && typeof exported.default === "function" ? exported.default : null);
      if (entry) entry(api);
      bridge.profile = {
        loaded: true,
        path: profilePath,
        commands: Object.keys(profileCommands).sort()
      };
      log("profile loaded", { path: profilePath, commands: bridge.profile.commands });
      return true;
    } catch (error) {
      bridge.profile = { loaded: false, error: noteError(error) };
      log("profile load failed", { error: bridge.lastError });
      return false;
    }
  }
  // ---------------------------------------------------------------------------
  // Startup.
  //
  // Ordering matters here in a way that is easy to get wrong: engine classes do
  // not all exist when the bridge is injected (document_start), so hook
  // installation retries on a timer and again on window load. Everything else —
  // transport, state, the lock/option tickers — can start immediately.
  // ---------------------------------------------------------------------------

  const HOOK_RETRY_MS = 500;
  const HOOK_RETRY_LIMIT = 120;       // ~60s, enough for a slow disk + big game
  const WORLD_OPTION_MS = 500;        // fields the game also writes
  const VITALS_GUARD_MS = 100;        // beat direct _hp writes
  const STATE_WRITE_MS = 1000;
  const COMMAND_POLL_MS = 250;

  ensureDir();
  log("bridge injected", { href: location.href, gameKey, bridgeVersion: bridge.version });

  loadProfile();

  let hookRetries = 0;
  const hookTimer = setInterval(function () {
    hookRetries += 1;
    const summary = patchTrainerHooks();
    if (summary.count > 0 || hookRetries >= HOOK_RETRY_LIMIT) {
      clearInterval(hookTimer);
      log("hook install finished", { ...summary, retries: hookRetries });
      applyWorldOptions();
      writeState();
    }
  }, HOOK_RETRY_MS);

  // Plugins can replace prototypes after boot, so patch once more when the page
  // is fully loaded — patchMethod makes the repeat harmless.
  window.addEventListener("load", function () {
    patchTrainerHooks();
    applyWorldOptions();
    ensureWindowShown("load");
  });

  // Window-show watchdog. A whole class of protected games boots with
  // "window": {"show": false} in package.json and relies on its startup chain
  // calling nw.Window.get().show() once ready. If that chain stalls (protection
  // hiccup, plugin error, timing), the page — and this bridge — keeps running
  // with no visible window: "process alive, items listed, BGM audible, but no
  // game UI". While the window has never been visible, re-assert show() every
  // few seconds. Once the window has been seen visible even once the watchdog
  // disarms, so it never fights the user (minimize) or the game (intentional
  // hide) later on. show() on an already-visible window is a no-op.
  let windowWatchdogArmed = true;
  function ensureWindowShown(reason) {
    if (!windowWatchdogArmed) return;
    try {
      if (typeof nw === "undefined" || !nw.Window || typeof nw.Window.get !== "function") {
        windowWatchdogArmed = false; // not an NW page (e.g. test harness)
        return;
      }
      if (!document || document.visibilityState !== "hidden") {
        windowWatchdogArmed = false; // window shown (or state unknown) — game is fine
        return;
      }
      const win = nw.Window.get();
      if (!win || typeof win.show !== "function") return;
      win.show();
      log("window show asserted", { reason });
    } catch (error) {
      noteError(error);
    }
  }
  const windowWatchdogTimer = setInterval(function () { ensureWindowShown("watchdog"); }, 1500);
  setTimeout(function () {
    clearInterval(windowWatchdogTimer);
    windowWatchdogArmed = false;
  }, 30000);

  connectWs();
  writeState();

  setInterval(applyWorldOptions, WORLD_OPTION_MS);
  setInterval(preserveVitalsTick, VITALS_GUARD_MS);
  setInterval(writeState, STATE_WRITE_MS);
  setInterval(pollCommands, COMMAND_POLL_MS);
})();
// @rmch-iife-close
